window.__TNPSC_REGISTER_TEST__("gk", 10, [{"id":901,"subject":"gk","testNumber":10,"question":"தொலைபேசியை (Telephone) முதன்முதலில் கண்டுபிடித்த அறிவியலாளர் யார்?","options":["குக்லீல்மோ மார்க்கோனி","தாமஸ் ஆல்வா எடிசன்","மைக்கேல் பாரடே","அலெக்சாண்டர் கிரஹாம் பெல்"],"correctAnswer":3,"explanation":"அலெக்சாண்டர் கிரஹாம் பெல் 1876-ஆம் ஆண்டு தொலைபேசியைக் கண்டுபிடித்து அதற்கான காப்புரிமையைப் பெற்றார். மனிதக் குரலை மின்சமிக்கைகளாக மாற்றி நீண்ட தொலைவிற்கு அனுப்பும் தகவல் தொடர்புப் புரட்சிக்கு இது அடித்தளமிட்டது. மார்க்கோனி வானொலியையும், எடிசன் மின்விளக்கையும் கண்டுபிடித்தனர்.","difficulty":"easy","topic":"அறிவியல் கண்டுபிடிப்புகள்"},{"id":902,"subject":"gk","testNumber":10,"question":"வணிக ரீதியாகப் பயன்படுத்தக்கூடிய ஒளிரும் மின்விளக்கையும் (Electric Bulb) கிராமபோனையும் கண்டுபிடித்தவர் யார்?","options":["தாமஸ் ஆல்வா எடிசன்","நிக்கோலா டெஸ்லா","ஜேம்ஸ் வாட்","பெஞ்சமின் பிராங்க்ளின்"],"correctAnswer":0,"explanation":"அமெரிக்க அறிவியலாளரான தாமஸ் ஆல்வா எடிசன் 1879-ஆம் ஆண்டு நீண்ட நேரம் ஒளிரும் மின்விளக்கைக் கண்டுபிடித்தார். இவர் கிராமபோன் (ஒலிப்பதிவுக் கருவி), திரைப்படக் கருவி உள்ளிட்ட ஆயிரத்திற்கும் மேற்பட்ட கண்டுபிடிப்புகளுக்கான காப்புரிமைகளைப் பெற்றுள்ளார்.","difficulty":"easy","topic":"அறிவியல் கண்டுபிடிப்புகள்"},{"id":903,"subject":"gk","testNumber":10,"question":"நீராவி இயந்திரத்தை (Steam Engine) திறம்பட மேம்படுத்தித் தொழிற்புரட்சிக்கு வித்திட்ட ஸ்காட்லாந்து பொறியாளர் யார்?","options":["ஜார்ஜ் ஸ்டீபன்சன்","ஜேம்ஸ் வாட்","ருடால்ஃப் டீசல்","ஹென்றி ஃபோர்டு"],"correctAnswer":1,"explanation":"ஜேம்ஸ் வாட் 1769-ஆம் ஆண்டு தனி குளிரூட்டியுடன் (Separate Condenser) கூடிய திறன்மிக்க நீராவி இயந்திரத்தை உருவாக்கினார். இதன் மூலம் தொழிற்சாலைகள் மற்றும் போக்குவரத்துத் துறைகளில் மாபெரும் தொழிற்புரட்சி ஏற்பட்டது. இவரது நினைவாகவே திறனின் SI அலகிற்கு 'வாட்' (Watt) எனப் பெயரிடப்பட்டது.","difficulty":"easy","topic":"அறிவியல் கண்டுபிடிப்புகள்"},{"id":904,"subject":"gk","testNumber":10,"question":"உலகின் முதல் நுண்ணுயிர் எதிர்ப்பியான (Antibiotic) 'பென்சிலின்' மருந்தை 1928-ஆம் ஆண்டு கண்டுபிடித்தவர் யார்?","options":["சர் அலெக்சாண்டர் பிளெமிங்","லூயிஸ் பாஸ்டர்","எட்வர்ட் ஜென்னர்","ராபர்ட் கோச்"],"correctAnswer":0,"explanation":"ஸ்காட்லாந்து நுண்ணுயிரியலாளரான சர் அலெக்சாண்டர் பிளெமிங் 1928-ஆம் ஆண்டு 'பென்சிலியம் நொட்டேட்டம்' எனும் பூஞ்சையிலிருந்து பென்சிலின் மருந்தைக் கண்டுபிடித்தார். இது பாக்டீரியா தொற்று நோய்களைக் குணப்படுத்தும் மருத்துவப் புரட்சியை ஏற்படுத்தியது. இக்கண்டுபிடிப்பிற்காக 1945-இல் நோபல் பரிசு வழங்கப்பட்டது.","difficulty":"easy","topic":"அறிவியல் கண்டுபிடிப்புகள்"},{"id":905,"subject":"gk","testNumber":10,"question":"1895-ஆம் ஆண்டு எக்ஸ்-கதிர்களைக் (X-Rays) கண்டுபிடித்து, இயற்பியலுக்கான முதல் நோபல் பரிசைப் பெற்றவர் யார்?","options":["ஜே.ஜே. தாம்சன்","ஹென்றி பெக்கோரல்","எர்னஸ்ட் ரூதர்ஃபோர்டு","வில்லெம் கான்ராட் ராண்ட்ஜன்"],"correctAnswer":3,"explanation":"ஜெர்மனி இயற்பியலாளரான வில்லெம் கான்ராட் ராண்ட்ஜன் 1895-ஆம் ஆண்டு எக்ஸ்-கதிர்களைக் கண்டுபிடித்தார். மருத்துவத் துறையில் எலும்பு முறிவுகளைக் கண்டறிய இக்கதிர்கள் பெரிதும் பயன்படுகின்றன. இதற்காக 1901-ஆம் ஆண்டின் முதல் இயற்பியல் நோபல் பரிசு இவருக்கு வழங்கப்பட்டது.","difficulty":"medium","topic":"அறிவியல் கண்டுபிடிப்புகள்"},{"id":906,"subject":"gk","testNumber":10,"question":"ரேடியம் (Radium) மற்றும் பொலோனியம் (Polonium) ஆகிய கதிரியக்கத் தனிமங்களைக் கண்டுபிடித்து இரு துறைகளில் நோபல் பரிசு பெற்றவர் யார்?","options":["ஓட்டோ ஹான்","மேரி கியூரி","ரோசலிண்ட் பிராங்க்ளின்","நீல்ஸ் போர்"],"correctAnswer":1,"explanation":"மேரி கியூரி தனது கணவர் பியரி கியூரியுடன் இணைந்து 1898-ஆம் ஆண்டு ரேடியம் மற்றும் பொலோனியம் ஆகிய கதிரியக்கத் தனிமங்களைக் கண்டுபிடித்தார். இயற்பியல் (1903) மற்றும் வேதியியல் (1911) ஆகிய இரு வெவ்வேறு அறிவியல் துறைகளில் நோபல் பரிசு பெற்ற ஒரே அறிவியலாளர் மேரி கியூரி ஆவார்.","difficulty":"medium","topic":"அறிவியல் கண்டுபிடிப்புகள்"},{"id":907,"subject":"gk","testNumber":10,"question":"உலகில் முதன்முதலில் செயல்படும் தொலைக்காட்சி (Television) அமைப்பை உருவாக்கிக் காட்டிய அறிவியலாளர் யார்?","options":["கலிலியோ கலிலி","ஜான் லோகி பேர்ட்","சார்லஸ் பாபேஜ்","ஆண்ட்ரே மேரி ஆம்பியர்"],"correctAnswer":1,"explanation":"ஸ்காட்லாந்து பொறியாளரான ஜான் லோகி பேர்ட் (John Logie Baird) 1926-ஆம் ஆண்டு இயந்திரவியல் அடிப்படையிலான முதல் தொலைக்காட்சி அமைப்பைப் பொதுமக்கள் முன் வெற்றிகரமாக இயக்கி காட்டினார். இதனால் இவர் 'தொலைக்காட்சியின் தந்தை' எனப் போற்றப்படுகிறார்.","difficulty":"easy","topic":"அறிவியல் கண்டுபிடிப்புகள்"},{"id":908,"subject":"gk","testNumber":10,"question":"1903-ஆம் ஆண்டு முதன்முதலில் இயந்திரம் பொருத்தப்பட்ட விமானத்தை (Aeroplane) வெற்றிகரமாகப் பறக்கவிட்டவர்கள் யார்?","options":["ரைட் சகோதரர்கள்","லூமியர் சகோதரர்கள்","மாண்ட் கோல்பியர் சகோதரர்கள்","கிரீம் சகோதரர்கள்"],"correctAnswer":0,"explanation":"அமெரிக்காவைச் சேர்ந்த ஆர்வில் ரைட் மற்றும் வில்பர் ரைட் ஆகிய ரைட் சகோதரர்கள் 1903 டிசம்பர் 17-ஆம் தேதி வடக்கு கரோலினாவின் கிட்டி ஹாக் பகுதியில் உலகின் முதல் இயந்திர விமானத்தை வெற்றிகரமாகப் பறக்கவிட்டனர். இது நவீன வான்வெளிப் போக்குவரத்தின் தொடக்கமாகும்.","difficulty":"easy","topic":"அறிவியல் கண்டுபிடிப்புகள்"},{"id":909,"subject":"gk","testNumber":10,"question":"பெரியம்மை (Smallpox) நோய்க்கு உலகின் முதல் தடுப்பூசியைக் கண்டுபிடித்து 'நோயெதிர்ப்பு இயலின் தந்தை' என அழைக்கப்படுபவர் யார்?","options":["வில்லியம் ஹார்வி","லூயிஸ் பாஸ்டர்","எட்வர்ட் ஜென்னர்","ஜோனஸ் சால்க்"],"correctAnswer":2,"explanation":"இங்கிலாந்து மருத்துவரான எட்வர்ட் ஜென்னர் 1796-ஆம் ஆண்டு பெரியம்மை நோய்க்கான முதல் தடுப்பூசியைக் (Vaccination) கண்டுபிடித்தார். பசுவம்மை நுண்ணுயிரி பெரியம்மைக்கு எதிரான நோய் எதிர்ப்புச் சக்தியைத் தருவதை இவர் நிரூபித்தார். ஜோனஸ் சால்க் போலியோ தடுப்பூசியைக் கண்டுபிடித்தார்.","difficulty":"medium","topic":"அறிவியல் கண்டுபிடிப்புகள்"},{"id":910,"subject":"gk","testNumber":10,"question":"ஐரோப்பாவில் நகரும் உலோக எழுத்துக்களுடனான அச்சு இயந்திரத்தை (Printing Press) கண்டுபிடித்தவர் யார்?","options":["ஜோஹன்னஸ் குட்டன்பெர்க்","வில்லியம் காக்ஸ்டன்","ஐசக் நியூட்டன்","லியனார்டோ டாவின்சி"],"correctAnswer":0,"explanation":"ஜெர்மனியைச் சேர்ந்த ஜோஹன்னஸ் குட்டன்பெர்க் சுமார் 1440-ஆம் ஆண்டில் நகரும் உலோக எழுத்துக்களைக் கொண்ட அச்சு இயந்திரத்தைக் கண்டுபிடித்தார். இதன் மூலம் புத்தகங்கள் மிகுந்த எண்ணிக்கையில் அச்சிடப்பட்டு கல்வி மற்றும் அறிவியல் அறிவு உலகம் முழுவதும் விரைவாகப் பரவியது.","difficulty":"medium","topic":"அறிவியல் கண்டுபிடிப்புகள்"},{"id":911,"subject":"gk","testNumber":10,"question":"டைனமைட் (Dynamite) எனும் வெடிபொருளைக் கண்டுபிடித்து, பின்னர் உலகப் புகழ்பெற்ற நோபல் பரிசு அறக்கட்டளையை நிறுவியவர் யார்?","options":["ராபர்ட் ஓப்பன்ஹைமர்","ஆல்பர்ட் ஐன்ஸ்டீன்","மைக்கேல் பாரடே","ஆல்பிரட் நோபல்"],"correctAnswer":3,"explanation":"சுவீடன் நாட்டு வேதியியலாளரும் பொறியாளருமான ஆல்பிரட் நோபல் 1867-ஆம் ஆண்டு டைனமைட் எனும் வெடிபொருளைக் கண்டுபிடித்தார். தனது சொத்துக்களைக் கொண்டு மனித குலத்திற்குப் பெரும் பங்காற்றுபவர்களைக் கௌரவிக்க நோபல் பரிசு வழங்க உயில் எழுதி வைத்தார். 1901 முதல் நோபல் பரிசு வழங்கப்படுகிறது.","difficulty":"easy","topic":"அறிவியல் கண்டுபிடிப்புகள்"},{"id":912,"subject":"gk","testNumber":10,"question":"ஒளி ஒரு ஊடகத்தின் வழியே செல்லும்போது ஏற்படும் அலைநீள மாற்றத்தை விளக்கும் 'ராமன் விளைவை' (Raman Effect) கண்டுபிடித்தவர் யார்?","options":["சுப்பிரமணியன் சந்திரசேகர்","சர் சி.வி. ராமன்","மேக்நாத் சஹா","சத்யேந்திர நாத் போஸ்"],"correctAnswer":1,"explanation":"சர் சந்திரசேகர வெங்கட ராமன் (சர் சி.வி. ராமன்) 1928 பிப்ரவரி 28-ஆம் தேதி ஒளிச்சிதறல் குறித்த 'ராமன் விளைவை' அறிவித்தார். இக்கண்டுபிடிப்பிற்காக 1930-ஆம் ஆண்டு இயற்பியலுக்கான நோபல் பரிசைப் பெற்ற முதல் ஆசிய அறிவியலாளர் என்ற பெருமையைப் பெற்றார்.","difficulty":"easy","topic":"அறிவியல் கண்டுபிடிப்புகள்"},{"id":913,"subject":"gk","testNumber":10,"question":"வளிமண்டல அழுத்தத்தை (Atmospheric Pressure) அளவிடப் பயன்படும் அறிவியல் கருவி எது?","options":["கலர்மீட்டர்","ஹைக்ரோமீட்டர்","ஸ்பெக்ட்ரோமீட்டர்","பாரோமீட்டர்"],"correctAnswer":3,"explanation":"வளிமண்டல அழுத்தத்தை அளவிட 'பாரோமீட்டர்' (காற்றழுத்தமானி) பயன்படுகிறது. இதனை இத்தாலிய அறிவியலாளர் இவாஞ்சலிஸ்டா டாரிசெல்லி 1643-இல் கண்டுபிடித்தார். பாரோமீட்டரில் பாதரச அளவு திடீரெனக் குறைந்தால் புயல் வீசக்கூடும் என்பதை முன்கூட்டியே அறியலாம்.","difficulty":"easy","topic":"அறிவியல் கருவிகள்"},{"id":914,"subject":"gk","testNumber":10,"question":"வளிமண்டலக் காற்றில் உள்ள ஈரப்பதத்தின் (Humidity) அளவைக் கணக்கிடப் பயன்படும் கருவி எது?","options":["ஹைக்ரோமீட்டர்","ஹைட்ரோமீட்டர்","மழைமானி","தெர்மோமீட்டர்"],"correctAnswer":0,"explanation":"காற்றில் உள்ள நீராவியின் அளவை அதாவது ஈரப்பதத்தை அளவிட 'ஹைக்ரோமீட்டர்' (ஈரப்பதமானி) பயன்படுகிறது. மாணவர்கள் கவனிக்க வேண்டியது: 'ஹைட்ரோமீட்டர்' என்பது திரவங்களின் ஒப்படர்த்தியை அளவிடப் பயன்படும் வேறொரு கருவியாகும்.","difficulty":"medium","topic":"அறிவியல் கருவிகள்"},{"id":915,"subject":"gk","testNumber":10,"question":"வானிலை ஆய்வு நிலையங்களில் காற்றின் வேகத்தை (Wind Speed) அளவிடப் பயன்படும் கருவி எது?","options":["ஸ்பீடோமீட்டர்","டேக்கோமீட்டர்","அனிமோமீட்டர்","ஓடோமீட்டர்"],"correctAnswer":2,"explanation":"காற்றின் வேகத்தை அளவிட 'அனிமோமீட்டர்' (காற்றுவேகமானி) பயன்படுகிறது. காற்றின் திசையை அறிய காற்றுத் திசைகாட்டி (Wind Vane) பயன்படுகிறது. ஓடோமீட்டர் வாகனங்கள் கடந்த தொலைவையும், ஸ்பீடோமீட்டர் வாகனங்களின் வேகத்தையும் அளவிடுகின்றன.","difficulty":"medium","topic":"அறிவியல் கருவிகள்"},{"id":916,"subject":"gk","testNumber":10,"question":"பாலின் அடர்த்தி மற்றும் தூய்மையைக் கண்டறியப் பயன்படும் அறிவியல் கருவி எது?","options":["லாக்டோமீட்டர்","கலோரிமீட்டர்","பைரோமீட்டர்","சாக்ரோமீட்டர்"],"correctAnswer":0,"explanation":"பாலின் ஒப்படர்த்தியை அளவிட்டு அதில் நீர் கலக்கப்பட்டுள்ளதா என்பதைக் கண்டறிய 'லாக்டோமீட்டர்' (பால்மானி) பயன்படுகிறது. இது ஆர்க்கிமிடிஸ் மிதத்தல் தத்துவத்தின் அடிப்படையில் செயல்படுகிறது. கலோரிமீட்டர் வெப்ப அளவையும், பைரோமீட்டர் மிக அதிக வெப்பநிலையையும் அளவிடுகின்றன.","difficulty":"easy","topic":"அறிவியல் கருவிகள்"},{"id":917,"subject":"gk","testNumber":10,"question":"மனிதனின் இரத்த அழுத்தத்தை (Blood Pressure) அளவிட மருத்துவமனைகளில் பயன்படுத்தப்படும் கருவி எது?","options":["ஆடியோமீட்டர்","ஸ்பிக்மோமானோமீட்டர்","ஸ்டெதாஸ்கோப்","எலக்ட்ரோ கார்டியோகிராப்"],"correctAnswer":1,"explanation":"மனிதனின் இரத்த அழுத்தத்தை (சாதாரண அளவு 120/80 mmHg) அளவிட 'ஸ்பிக்மோமானோமீட்டர்' (Sphygmomanometer) பயன்படுகிறது. ஸ்டெதாஸ்கோப் இதயத் துடிப்பு மற்றும் நுரையீரல் ஒலியைக் கேட்கவும், எலக்ட்ரோ கார்டியோகிராப் (ECG) இதயத்தின் மின் செயல்பாட்டைப் பதிவு செய்யவும் பயன்படுகின்றன.","difficulty":"medium","topic":"அறிவியல் கருவிகள்"},{"id":918,"subject":"gk","testNumber":10,"question":"ஒரு மின்சுற்றில் பாயும் மின்னோட்டத்தின் (Electric Current) அளவை ஆம்பியர் அலகில் அளவிடும் கருவி எது? இது மின்சுற்றில் எவ்வாறு இணைக்கப்படும்?","options":["அம்மீட்டர் — பக்க இணைப்பில்","வோல்ட்மீட்டர் — தொடரிணைப்பில்","அம்மீட்டர் — தொடரிணைப்பில்","கால்வனோமீட்டர் — பக்க இணைப்பில்"],"correctAnswer":2,"explanation":"மின்சுற்றில் பாயும் மின்னோட்டத்தை அளவிட 'அம்மீட்டர்' (Ammeter) பயன்படுகிறது. மின்னோட்டம் முழுவதும் கருவியின் வழியே செல்ல வேண்டும் என்பதால் அம்மீட்டர் எப்போதும் மின்சுற்றில் தொடரிணைப்பில் (Series) இணைக்கப்படுகிறது. இதற்கு மிகக் குறைந்த மின்தடை இருக்கும்.","difficulty":"hard","topic":"அறிவியல் கருவிகள்"},{"id":919,"subject":"gk","testNumber":10,"question":"ஒரு மின்சுற்றின் இரு புள்ளிகளுக்கு இடையேயான மின்னழுத்த வேறுபாட்டை (Potential Difference) அளவிடப் பயன்படும் கருவி எது?","options":["ஓம்மீட்டர்","வாட்மீட்டர்","அம்மீட்டர்","வோல்ட்மீட்டர்"],"correctAnswer":3,"explanation":"மின்சுற்றின் இரு முனைகளுக்கு இடையேயான மின்னழுத்த வேறுபாட்டை வோல்ட் அலகில் அளவிட 'வோல்ட்மீட்டர்' (Voltmeter) பயன்படுகிறது. இது எப்போதும் மின்சுற்றில் பக்க இணைப்பில் (Parallel) இணைக்கப்படுகிறது. ஓம்மீட்டர் மின்தடையையும், வாட்மீட்டர் மின்திறனையும் அளவிடும்.","difficulty":"medium","topic":"அறிவியல் கருவிகள்"},{"id":920,"subject":"gk","testNumber":10,"question":"கடலின் ஆழத்தை (Depth of the Ocean) மீயொலி அலைகளின் உதவியுடன் அளவிடப் பயன்படும் கருவி எது?","options":["மானோமீட்டர்","ஃபாதோமீட்டர்","சீஸ்மோகிராஃப்","அல்டிமீட்டர்"],"correctAnswer":1,"explanation":"கடலின் ஆழத்தை அளவிட 'ஃபாதோமீட்டர்' (Fathometer) எனும் கருவி பயன்படுகிறது. இது ஒலி அலைகளைக் கடலின் அடிப்பகுதிக்கு அனுப்பி, அவை எதிரொலித்துத் திரும்பும் நேரத்தைக் கொண்டு கடலின் ஆழத்தைக் கணக்கிடுகிறது. ஒரு ஃபாதம் என்பது 6 அடிக்குச் சமம்.","difficulty":"medium","topic":"அறிவியல் கருவிகள்"},{"id":921,"subject":"gk","testNumber":10,"question":"விமானம் கடல் மட்டத்திலிருந்து எவ்வளவு உயரத்தில் பறக்கிறது என்பதைக் கண்டறியப் பயன்படும் கருவி எது?","options":["ரேடார்","அல்டிமீட்டர்","ஃபாதோமீட்டர்","பெரிஸ்கோப்"],"correctAnswer":1,"explanation":"கடல் மட்டத்திலிருந்து ஒரு பொருள் அல்லது விமானம் உள்ள உயரத்தை (Altitude) அளவிட 'அல்டிமீட்டர்' (உயரமானி) பயன்படுகிறது. உயரம் செல்லச் செல்ல வளிமண்டல அழுத்தம் குறையும் தத்துவத்தின் அடிப்படையில் இது செயல்படுகிறது. பெரிஸ்கோப் நீர்மூழ்கிக் கப்பல்களில் பயன்படுகிறது.","difficulty":"medium","topic":"அறிவியல் கருவிகள்"},{"id":922,"subject":"gk","testNumber":10,"question":"பொருத்துக: அறிவியல் கருவிகள் மற்றும் அவற்றின் பயன்பாடுகள்.\n(a) பாரோமீட்டர் - 1. கடலின் ஆழம்\n(b) அனிமோமீட்டர் - 2. வளிமண்டல அழுத்தம்\n(c) லாக்டோமீட்டர் - 3. காற்றின் வேகம்\n(d) ஃபாதோமீட்டர் - 4. பாலின் தூய்மை","options":["a-4, b-3, c-2, d-1","a-2, b-4, c-3, d-1","a-3, b-2, c-1, d-4","a-2, b-3, c-4, d-1"],"correctAnswer":3,"explanation":"பாரோமீட்டர் வளிமண்டல அழுத்தத்தையும் (2), அனிமோமீட்டர் காற்றின் வேகத்தையும் (3), லாக்டோமீட்டர் பாலின் தூய்மையையும் (4), ஃபாதோமீட்டர் கடலின் ஆழத்தையும் (1) அளவிடப் பயன்படுகின்றன. எனவே சரியான பொருத்தம் a-2, b-3, c-4, d-1 ஆகும்.","difficulty":"hard","topic":"அறிவியல் கருவிகள்"},{"id":923,"subject":"gk","testNumber":10,"question":"சர் சி.வி. ராமன் 'ராமன் விளைவை' கண்டுபிடித்ததைப் போற்றும் வகையில் இந்தியாவில் 'தேசிய அறிவியல் தினம்' எப்போது கொண்டாடப்படுகிறது?","options":["பிப்ரவரி 28","மார்ச் 28","நவம்பர் 7","ஜனவரி 28"],"correctAnswer":0,"explanation":"சர் சி.வி. ராமன் 1928 பிப்ரவரி 28-ஆம் தேதி 'ராமன் விளைவை' உலகுக்கு அறிவித்தார். அந்த வரலாற்றுச் சிறப்புமிக்க நாளை நினைவுகூரும் வகையில் 1987-ஆம் ஆண்டு முதல் ஒவ்வொரு ஆண்டும் பிப்ரவரி 28-ஆம் தேதி இந்தியாவில் 'தேசிய அறிவியல் தினம்' கொண்டாடப்படுகிறது.","difficulty":"easy","topic":"முக்கிய தினங்கள்"},{"id":924,"subject":"gk","testNumber":10,"question":"சுவாமி விவேகானந்தரின் பிறந்தநாளான ஜனவரி 12-ஆம் தேதி இந்தியாவில் எந்தத் தினமாகக் கொண்டாடப்படுகிறது?","options":["தேசியக் கல்வி தினம்","தேசிய இளைஞர் தினம்","தேசிய ஒருமைப்பாட்டு தினம்","தேசிய நல்லாட்சி தினம்"],"correctAnswer":1,"explanation":"சுவாமி விவேகானந்தரின் (பிறப்பு: 1863 ஜனவரி 12) தத்துவங்களும் கருத்துக்களும் இளைஞர்களுக்கு ஊக்கமளிப்பதால், இந்திய அரசு 1984-இல் அறிவித்தபடி 1985 முதல் ஆண்டுதோறும் ஜனவரி 12-ஆம் தேதி 'தேசிய இளைஞர் தினம்' (National Youth Day) கொண்டாடப்படுகிறது.","difficulty":"easy","topic":"முக்கிய தினங்கள்"},{"id":925,"subject":"gk","testNumber":10,"question":"இந்தியத் தேர்தல் ஆணையம் 1950-இல் நிறுவப்பட்டதை நினைவுகூரும் வகையில் 'தேசிய வாக்காளர் தினம்' எப்போது கொண்டாடப்படுகிறது?","options":["ஜனவரி 30","ஜனவரி 26","ஜனவரி 24","ஜனவரி 25"],"correctAnswer":3,"explanation":"இந்தியத் தேர்தல் ஆணையம் 1950 ஜனவரி 25-ஆம் தேதி நிறுவப்பட்டது. இளம் வாக்காளர்களை ஊக்குவிக்கவும் வாக்களிப்பதன் அவசியத்தை உணர்த்தவும் 2011-ஆம் ஆண்டு முதல் ஒவ்வொரு ஆண்டும் ஜனவரி 25-ஆம் தேதி 'தேசிய வாக்காளர் தினம்' கொண்டாடப்படுகிறது.","difficulty":"easy","topic":"முக்கிய தினங்கள்"},{"id":926,"subject":"gk","testNumber":10,"question":"பன்மொழிப் பண்பாட்டைப் போற்றும் வகையில் யுனெஸ்கோவால் அறிவிக்கப்பட்ட 'உலகத் தாய்மொழி தினம்' எந்த நாளில் அனுசரிக்கப்படுகிறது?","options":["செப்டம்பர் 14","பிப்ரவரி 21","பிப்ரவரி 14","மார்ச் 21"],"correctAnswer":1,"explanation":"யுனெஸ்கோ (UNESCO) அமைப்பால் 1999-இல் அறிவிக்கப்பட்டு, 2000-ஆம் ஆண்டு முதல் ஒவ்வொரு ஆண்டும் பிப்ரவரி 21-ஆம் தேதி 'சர்வதேசத் தாய்மொழி தினம்' (International Mother Language Day) கொண்டாடப்படுகிறது. மொழி மற்றும் பண்பாட்டுப் பன்முகத்தன்மையைப் பாதுகாப்பதே இதன் நோக்கமாகும்.","difficulty":"medium","topic":"முக்கிய தினங்கள்"},{"id":927,"subject":"gk","testNumber":10,"question":"பெண்களின் சம உரிமை மற்றும் சாதனைகளைப் போற்றும் 'சர்வதேச மகளிர் தினம்' (International Women's Day) எப்போது கொண்டாடப்படுகிறது?","options":["மே 8","ஏப்ரல் 8","மார்ச் 8","பிப்ரவரி 13"],"correctAnswer":2,"explanation":"சமூக, பொருளாதார, பண்பாட்டு மற்றும் அரசியல் துறைகளில் பெண்களின் பங்களிப்பைக் கௌரவிக்க உலகம் முழுவதும் ஒவ்வொரு ஆண்டும் மார்ச் 8-ஆம் தேதி 'சர்வதேச மகளிர் தினம்' கொண்டாடப்படுகிறது. ஐ.நா. சபை 1975-ஆம் ஆண்டை சர்வதேச மகளிர் ஆண்டாக அறிவித்து இதனை அதிகாரப்பூர்வமாகக் கொண்டாடத் தொடங்கியது.","difficulty":"easy","topic":"முக்கிய தினங்கள்"},{"id":928,"subject":"gk","testNumber":10,"question":"நன்னீரின் முக்கியத்துவம் மற்றும் நீர் மேலாண்மை குறித்த விழிப்புணர்வுக்காக 'உலக நீர் தினம்' (World Water Day) எந்த நாளில் அனுசரிக்கப்படுகிறது?","options":["மார்ச் 22","ஜூன் 8","ஏப்ரல் 22","மார்ச் 21"],"correctAnswer":0,"explanation":"ஐக்கிய நாடுகள் சபையின் தீர்மானத்தின்படி 1993-ஆம் ஆண்டு முதல் ஒவ்வொரு ஆண்டும் மார்ச் 22-ஆம் தேதி 'உலக நீர் தினம்' அனுசரிக்கப்படுகிறது. மார்ச் 21 உலகக் காடுகள் தினமாகவும், மார்ச் 23 உலக வானிலை தினமாகவும் அனுசரிக்கப்படுகின்றன.","difficulty":"easy","topic":"முக்கிய தினங்கள்"},{"id":929,"subject":"gk","testNumber":10,"question":"உலக சுகாதார நிறுவனம் (WHO) தோற்றுவிக்கப்பட்டதைக் குறிக்கும் வகையில் 'உலக சுகாதார தினம்' எப்போது கொண்டாடப்படுகிறது?","options":["ஏப்ரல் 7","மே 7","ஏப்ரல் 17","ஏப்ரல் 1"],"correctAnswer":0,"explanation":"உலக சுகாதார நிறுவனம் (World Health Organization) 1948 ஏப்ரல் 7-ஆம் தேதி நிறுவப்பட்டது. இதன் நினைவாக 1950 முதல் ஆண்டுதோறும் ஏப்ரல் 7-ஆம் தேதி 'உலக சுகாதார தினம்' (World Health Day) உலகம் முழுவதும் அனுசரிக்கப்படுகிறது.","difficulty":"medium","topic":"முக்கிய தினங்கள்"},{"id":930,"subject":"gk","testNumber":10,"question":"புவியைப் பாதுகாப்பதற்கான சுற்றுச்சூழல் விழிப்புணர்வை ஏற்படுத்த 'உலகப் பூமி தினம்' (Earth Day) எந்த நாளில் கொண்டாடப்படுகிறது?","options":["மார்ச் 22","மே 22","ஏப்ரல் 22","ஜூன் 22"],"correctAnswer":2,"explanation":"1970-ஆம் ஆண்டு முதல் ஒவ்வொரு ஆண்டும் ஏப்ரல் 22-ஆம் தேதி 'உலகப் பூமி தினம்' (Earth Day) கொண்டாடப்படுகிறது. மார்ச் 22 உலக நீர் தினமாகவும், மே 22 சர்வதேசப் பல்லுயிர் தினமாகவும் அனுசரிக்கப்படுவது குறிப்பிடத்தக்கது.","difficulty":"easy","topic":"முக்கிய தினங்கள்"},{"id":931,"subject":"gk","testNumber":10,"question":"ஐக்கிய நாடுகள் சபையால் அறிவிக்கப்பட்ட 'உலக சுற்றுச்சூழல் தினம்' (World Environment Day) ஆண்டுதோறும் எப்போது கொண்டாடப்படுகிறது?","options":["ஜூன் 5","ஜூலை 5","ஆகஸ்ட் 5","மே 5"],"correctAnswer":0,"explanation":"1972-ஆம் ஆண்டு ஸ்டாக்ஹோம் மாநாட்டின் தீர்மானத்தின்படி ஐ.நா. சபையால் அறிவிக்கப்பட்டு, 1973 முதல் ஒவ்வொரு ஆண்டும் ஜூன் 5-ஆம் தேதி 'உலக சுற்றுச்சூழல் தினம்' கொண்டாடப்படுகிறது. இயற்கை வளங்களைப் பாதுகாப்பதும் மாசுபாட்டைத் தடுப்பதும் இதன் முக்கிய நோக்கமாகும்.","difficulty":"easy","topic":"முக்கிய தினங்கள்"},{"id":932,"subject":"gk","testNumber":10,"question":"இந்தியாவின் முன்மொழிவை ஏற்று ஐக்கிய நாடுகள் சபை எந்த நாளை 'சர்வதேச யோகா தினமாக' (International Day of Yoga) அறிவித்தது?","options":["ஜூன் 21","ஜூன் 14","மே 21","ஜூலை 21"],"correctAnswer":0,"explanation":"வடக்கு அரைக்கோளத்தில் ஆண்டின் மிக நீண்ட பகல் பொழுதைக் கொண்ட ஜூன் 21-ஆம் தேதியை 'சர்வதேச யோகா தினமாக' ஐ.நா. பொதுச்சபை 2014 டிசம்பரில் அங்கீகரித்தது. 2015 ஜூன் 21 முதல் உலகம் முழுவதும் இத்தினம் கொண்டாடப்பட்டு வருகிறது.","difficulty":"easy","topic":"முக்கிய தினங்கள்"},{"id":933,"subject":"gk","testNumber":10,"question":"இந்தியாவின் இரண்டாவது குடியரசுத் தலைவரும் சிறந்த தத்துவ அறிஞருமான டாக்டர் சர்வபள்ளி ராதாகிருஷ்ணனின் பிறந்தநாளான செப்டம்பர் 5 எவ்வாறு கொண்டாடப்படுகிறது?","options":["தேசியக் கல்வி தினம்","உலக எழுத்தறிவு தினம்","தேசிய ஆசிரியர் தினம்","தேசியப் பொறியாளர் தினம்"],"correctAnswer":2,"explanation":"1888 செப்டம்பர் 5-ஆம் தேதி பிறந்த டாக்டர் எஸ். ராதாகிருஷ்ணனின் கல்விச் சேவையைப் போற்றும் வகையில் 1962 முதல் ஆண்டுதோறும் செப்டம்பர் 5 'தேசிய ஆசிரியர் தினம்' எனக் கொண்டாடப்படுகிறது. நவம்பர் 11 மௌலானா அபுல் கலாம் ஆசாத் பிறந்தநாள் தேசியக் கல்வி தினமாகும்.","difficulty":"easy","topic":"முக்கிய தினங்கள்"},{"id":934,"subject":"gk","testNumber":10,"question":"மாண்ட்ரீல் நெறிமுறை (Montreal Protocol) கையெழுத்தான நாளை நினைவுகூரும் 'உலக ஓசோன் தினம்' எப்போது அனுசரிக்கப்படுகிறது?","options":["ஆகஸ்ட் 16","செப்டம்பர் 16","அக்டோபர் 16","நவம்பர் 16"],"correctAnswer":1,"explanation":"ஓசோன் படலத்தைச் சிதைக்கும் குளோரோஃபுளோரோ கார்பன் (CFC) போன்ற பொருட்களைக் கட்டுப்படுத்த 1987 செப்டம்பர் 16-ஆம் தேதி மாண்ட்ரீல் நெறிமுறை கையெழுத்தானது. இதன் நினைவாக 1995 முதல் ஆண்டுதோறும் செப்டம்பர் 16 'உலக ஓசோன் தினம்' என அனுசரிக்கப்படுகிறது.","difficulty":"medium","topic":"முக்கிய தினங்கள்"},{"id":935,"subject":"gk","testNumber":10,"question":"ஐக்கிய நாடுகள் சபை (United Nations) 1945-இல் அதிகாரப்பூர்வமாகச் செயல்படத் தொடங்கிய நாளைக் குறிக்கும் 'ஐ.நா. தினம்' எப்போது கொண்டாடப்படுகிறது?","options":["அக்டோபர் 24","அக்டோபர் 16","அக்டோபர் 2","அக்டோபர் 31"],"correctAnswer":0,"explanation":"இரண்டாம் உலகப் போருக்குப் பிறகு உலக அமைதியைப் பாதுகாக்க 1945 அக்டோபர் 24-ஆம் தேதி ஐக்கிய நாடுகள் சபை அதிகாரப்பூர்வமாக நிறுவப்பட்டது. இதன் நினைவாக 1948 முதல் ஆண்டுதோறும் அக்டோபர் 24 'ஐ.நா. தினம்' (UN Day) எனக் கொண்டாடப்படுகிறது.","difficulty":"medium","topic":"முக்கிய தினங்கள்"},{"id":936,"subject":"gk","testNumber":10,"question":"இந்திய அரசியலமைப்பு நிர்ணய சபையால் அரசியலமைப்புச் சட்டம் ஏற்றுக்கொள்ளப்பட்டதைக் குறிக்கும் 'இந்திய அரசியலமைப்பு தினம்' எப்போது கொண்டாடப்படுகிறது?","options":["நவம்பர் 26","ஆகஸ்ட் 15","நவம்பர் 14","ஜனவரி 26"],"correctAnswer":0,"explanation":"இந்திய அரசியலமைப்புச் சட்டம் 1949 நவம்பர் 26-ஆம் தேதி அரசியலமைப்பு நிர்ணய சபையால் ஏற்றுக்கொள்ளப்பட்டு, 1950 ஜனவரி 26-இல் நடைமுறைக்கு வந்தது. டாக்டர் பி.ஆர். அம்பேத்கரின் பங்களிப்பைப் போற்றும் வகையில் 2015 முதல் நவம்பர் 26 'அரசியலமைப்பு தினமாக' (சம்விதான் திவஸ்) கொண்டாடப்படுகிறது.","difficulty":"medium","topic":"முக்கிய தினங்கள்"},{"id":937,"subject":"gk","testNumber":10,"question":"ஐ.நா. பொதுச்சபையால் உலகளாவிய மனித உரிமைகள் பிரகடனம் (UDHR) 1948-இல் ஏற்கப்பட்டதைக் குறிக்கும் 'மனித உரிமைகள் தினம்' எப்போது அனுசரிக்கப்படுகிறது?","options":["டிசம்பர் 1","டிசம்பர் 16","டிசம்பர் 10","டிசம்பர் 25"],"correctAnswer":2,"explanation":"ஐக்கிய நாடுகள் பொதுச்சபை 1948 டிசம்பர் 10-ஆம் தேதி உலகளாவிய மனித உரிமைகள் பிரகடனத்தை (Universal Declaration of Human Rights) ஏற்றுக்கொண்டது. இதன் நினைவாக ஆண்டுதோறும் டிசம்பர் 10-ஆம் தேதி 'உலக மனித உரிமைகள் தினம்' அனுசரிக்கப்படுகிறது. டிசம்பர் 1 உலக எய்ட்ஸ் தினமாகும்.","difficulty":"medium","topic":"முக்கிய தினங்கள்"},{"id":938,"subject":"gk","testNumber":10,"question":"உலகப் புகழ்பெற்ற இந்தியக் கணித மேதை சீனிவாச இராமானுஜனின் பிறந்தநாளான டிசம்பர் 22 இந்தியாவில் எவ்வாறு கொண்டாடப்படுகிறது?","options":["தேசியப் புள்ளியியல் தினம்","தேசிய அறிவியல் தினம்","தேசிய கணித தினம்","தேசியத் தொழில்நுட்ப தினம்"],"correctAnswer":2,"explanation":"தமிழ்நாட்டின் ஈரோட்டில் 1887 டிசம்பர் 22-ஆம் தேதி பிறந்த கணித மேதை சீனிவாச இராமானுஜனின் 125-வது பிறந்தநாளை முன்னிட்டு 2012-ஆம் ஆண்டு முதல் டிசம்பர் 22 'தேசிய கணித தினமாக' (National Mathematics Day) இந்திய அரசால் கொண்டாடப்படுகிறது.","difficulty":"medium","topic":"முக்கிய தினங்கள்"},{"id":939,"subject":"gk","testNumber":10,"question":"இந்திய ஹாக்கி விளையாட்டின் ஜாம்பவான் மேஜர் தயான் சந்த் அவர்களின் பிறந்தநாளான எந்தத் தேதி 'தேசிய விளையாட்டு தினமாக' கொண்டாடப்படுகிறது?","options":["ஆகஸ்ட் 29","ஜூலை 29","செப்டம்பர் 29","அக்டோபர் 29"],"correctAnswer":0,"explanation":"இந்தியாவிற்கு மூன்று ஒலிம்பிக் தங்கப் பதக்கங்களைப் பெற்றுத் தந்த ஹாக்கி வீரர் மேஜர் தயான் சந்த் அவர்களின் பிறந்தநாளான ஆகஸ்ட் 29-ஆம் தேதி 2012 முதல் 'தேசிய விளையாட்டு தினம்' (National Sports Day) எனக் கொண்டாடப்படுகிறது. இந்நாளில் தேசிய விளையாட்டு விருதுகள் வழங்கப்படுகின்றன.","difficulty":"hard","topic":"முக்கிய தினங்கள்"},{"id":940,"subject":"gk","testNumber":10,"question":"பொருத்துக: முக்கியத் தினங்கள் மற்றும் அவற்றின் தேதிகள்.\n(a) தேசிய வாக்காளர் தினம் - 1. செப்டம்பர் 16\n(b) உலக ஓசோன் தினம் - 2. நவம்பர் 26\n(c) அரசியலமைப்பு தினம் - 3. ஜனவரி 25\n(d) தேசிய கணித தினம் - 4. டிசம்பர் 22","options":["a-3, b-2, c-1, d-4","a-3, b-1, c-2, d-4","a-1, b-3, c-2, d-4","a-3, b-1, c-4, d-2"],"correctAnswer":1,"explanation":"தேசிய வாக்காளர் தினம் ஜனவரி 25 (3), உலக ஓசோன் தினம் செப்டம்பர் 16 (1), இந்திய அரசியலமைப்பு தினம் நவம்பர் 26 (2), மற்றும் தேசிய கணித தினம் டிசம்பர் 22 (4) ஆகும். எனவே சரியான பொருத்தம் a-3, b-1, c-2, d-4 ஆகும்.","difficulty":"hard","topic":"முக்கிய தினங்கள்"},{"id":941,"subject":"gk","testNumber":10,"question":"இந்திய தேசியக் கொடியை வடிவமைத்த ஆந்திரப் பிரதேசத்தைச் சேர்ந்த சுதந்திரப் போராட்ட வீரர் யார்?","options":["திருப்பூர் குமரன்","பங்கிம் சந்திர சட்டர்ஜி","பிங்காலி வெங்கையா","மாதம் பிகாஜி காமா"],"correctAnswer":2,"explanation":"இந்திய மூவர்ணத் தேசியக் கொடியை ஆந்திரப் பிரதேசத்தைச் சேர்ந்த பிங்காலி வெங்கையா வடிவமைத்தார். இதனை இந்திய அரசியலமைப்பு நிர்ணய சபை 1947 ஜூலை 22-ஆம் தேதி தேசியக் கொடியாக அதிகாரப்பூர்வமாக ஏற்றுக்கொண்டது. இதன் நடுவில் 24 ஆரங்கள் கொண்ட கருநீல அசோகச் சக்கரம் உள்ளது.","difficulty":"easy","topic":"தேசியச் சின்னங்கள்"},{"id":942,"subject":"gk","testNumber":10,"question":"இந்திய தேசியக் கொடியின் நீளம் மற்றும் அகலத்தின் அதிகாரப்பூர்வ விகிதம் (Length : Width) என்ன?","options":["2 : 3","4 : 3","5 : 3","3 : 2"],"correctAnswer":3,"explanation":"இந்தியக் கொடி விதிகளின்படி, தேசியக் கொடி செவ்வக வடிவில் இருக்க வேண்டும்; அதன் நீளம் மற்றும் அகலத்தின் விகிதம் 3 : 2 ஆகும். மேலே உள்ள காவி நிறம் தைரியம் மற்றும் தியாகத்தையும், நடுவில் உள்ள வெள்ளை நிறம் அமைதி மற்றும் நேர்மையையும், கீழே உள்ள பச்சை நிறம் செழிப்பு மற்றும் வளத்தையும் குறிக்கின்றன.","difficulty":"easy","topic":"தேசியச் சின்னங்கள்"},{"id":943,"subject":"gk","testNumber":10,"question":"இரவீந்திரநாத் தாகூரால் இயற்றப்பட்ட 'ஜன கண மன' பாடல் இந்திய தேசிய கீதமாக எப்போது ஏற்றுக்கொள்ளப்பட்டது? இதனைப் பாடுவதற்கான கால அளவு எவ்வளவு?","options":["1949 நவம்பர் 26 — 45 வினாடிகள்","1947 ஆகஸ்ட் 15 — 60 வினாடிகள்","1950 ஜனவரி 26 — 50 வினாடிகள்","1950 ஜனவரி 24 — 52 வினாடிகள்"],"correctAnswer":3,"explanation":"இரவீந்திரநாத் தாகூரால் வங்காள மொழியில் இயற்றப்பட்ட 'ஜன கண மன' பாடலின் இந்தி வடிவம் 1950 ஜனவரி 24-ஆம் தேதி அரசியலமைப்பு நிர்ணய சபையால் தேசிய கீதமாக ஏற்றுக்கொள்ளப்பட்டது. இதனை முழுமையாகப் பாடுவதற்குரிய கால அளவு 52 வினாடிகள் ஆகும். இது முதன்முதலில் 1911 டிசம்பர் 27-இல் கொல்கத்தா காங்கிரஸ் மாநாட்டில் பாடப்பட்டது.","difficulty":"medium","topic":"தேசியச் சின்னங்கள்"},{"id":944,"subject":"gk","testNumber":10,"question":"இந்தியாவின் தேசியப் பாடலான 'வந்தே மாதரம்' பங்கிம் சந்திர சட்டர்ஜி எழுதிய எந்தப் புகழ்பெற்ற நாவலிலிருந்து எடுக்கப்பட்டது?","options":["ஆனந்தமடம்","கபாலகுண்டலா","கீதாஞ்சலி","துர்கேசநந்தினி"],"correctAnswer":0,"explanation":"வங்காள எழுத்தாளர் பங்கிம் சந்திர சட்டர்ஜி 1882-இல் வெளியிட்ட 'ஆனந்தமடம்' என்ற புதினத்திலிருந்து 'வந்தே மாதரம்' என்ற தேசியப் பாடல் எடுக்கப்பட்டது. இதற்கு தேசிய கீதத்திற்கு இணையான சிறப்புத் தகுதியை 1950 ஜனவரி 24-ஆம் தேதி டாக்டர் இராஜேந்திர பிரசாத் அறிவித்தார்.","difficulty":"easy","topic":"தேசியச் சின்னங்கள்"},{"id":945,"subject":"gk","testNumber":10,"question":"இந்தியாவின் தேசியச் சின்னமான நான்கு சிங்கங்கள் கொண்ட சிற்பம் எந்த இடத்தில் உள்ள அசோகர் தூணின் உச்சியிலிருந்து எடுக்கப்பட்டது?","options":["சாஞ்சி","பாடலிபுத்திரம்","கயை","சாரநாத்"],"correctAnswer":3,"explanation":"உத்தரப் பிரதேசத்தில் உள்ள சாரநாத் அசோகர் தூணின் உச்சியில் உள்ள நான்கு சிங்கங்கள் கொண்ட சிற்பம் 1950 ஜனவரி 26-ஆம் தேதி இந்தியாவின் தேசியச் சின்னமாக ஏற்றுக்கொள்ளப்பட்டது. இதில் ஒரு சமயத்தில் மூன்று சிங்கங்கள் மட்டுமே பார்வைக்குத் தெரியும். அடிப்பகுதியில் யானை, குதிரை, காளை, சிங்கம் ஆகிய உருவங்கள் உள்ளன.","difficulty":"easy","topic":"தேசியச் சின்னங்கள்"},{"id":946,"subject":"gk","testNumber":10,"question":"இந்திய தேசியச் சின்னத்தின் அடிப்பகுதியில் பொறிக்கப்பட்டுள்ள 'சத்யமேவ ஜெயதே' (வாய்மையே வெல்லும்) என்ற வாசகம் எதிலிருந்து எடுக்கப்பட்டது?","options":["பகவத் கீதை","ரிக் வேதம்","முண்டக உபநிடதம்","கட உபநிடதம்"],"correctAnswer":2,"explanation":"இந்திய தேசியச் சின்னத்தின் கீழ்ப்பகுதியில் தேவநாகரி எழுத்து வடிவில் பொறிக்கப்பட்டுள்ள 'சத்யமேவ ஜெயதே' என்ற சமஸ்கிருத வாசகம் 'முண்டக உபநிடதத்திலிருந்து' (Mundaka Upanishad) எடுக்கப்பட்டது. இதற்கு 'வாய்மையே வெல்லும்' என்பது பொருளாகும்.","difficulty":"medium","topic":"தேசியச் சின்னங்கள்"},{"id":947,"subject":"gk","testNumber":10,"question":"இந்தியாவின் தேசிய விலங்கான 'வங்காளப் புலி' (Royal Bengal Tiger) எந்த ஆண்டில் தேசிய விலங்காக அறிவிக்கப்பட்டது?","options":["1973","1963","1980","1950"],"correctAnswer":0,"explanation":"1972-ஆம் ஆண்டு வரை சிங்கம் இந்தியாவின் தேசிய விலங்காக இருந்தது. புலிகளின் எண்ணிக்கையைப் பாதுகாக்க 1973-ஆம் ஆண்டு 'புலிகள் பாதுகாப்புத் திட்டம்' (Project Tiger) தொடங்கப்பட்டபோது, வங்காளப் புலி (Panthera tigris) இந்தியாவின் தேசிய விலங்காக அதிகாரப்பூர்வமாக அறிவிக்கப்பட்டது.","difficulty":"medium","topic":"தேசியச் சின்னங்கள்"},{"id":948,"subject":"gk","testNumber":10,"question":"இந்தியாவின் தேசியப் பறவை (மயில்), தேசிய மலர் (தாமரை), தேசிய மரம் (ஆலமரம்) மற்றும் தேசியப் பழம் (மாம்பழம்) ஆகியவற்றில் 1963-ஆம் ஆண்டு ஏற்றுக்கொள்ளப்பட்ட தேசியச் சின்னம் எது?","options":["ஆலமரம்","தாமரை","மாம்பழம்","மயில்"],"correctAnswer":3,"explanation":"தாமரை, ஆலமரம் மற்றும் மாம்பழம் ஆகிய மூன்றும் 1950-ஆம் ஆண்டிலேயே இந்தியாவின் தேசியச் சின்னங்களாக ஏற்றுக்கொள்ளப்பட்டன. இந்தியத் துணைக்கண்டத்திற்கு உரிய பறவையான மயில் (Pavo cristatus) 1963-ஆம் ஆண்டில் இந்தியாவின் தேசியப் பறவையாக அறிவிக்கப்பட்டது.","difficulty":"hard","topic":"தேசியச் சின்னங்கள்"},{"id":949,"subject":"gk","testNumber":10,"question":"இந்தியாவின் மிக நீளமான நதியான 'கங்கை நதி' எந்த ஆண்டில் இந்தியாவின் தேசிய நதியாக (National River) அறிவிக்கப்பட்டது?","options":["2010","2008","2014","2005"],"correctAnswer":1,"explanation":"சுமார் 2,525 கிலோமீட்டர் நீளமுடைய கங்கை நதி 2008 நவம்பர் 4-ஆம் தேதி இந்திய அரசால் தேசிய நதியாக அறிவிக்கப்பட்டது. இந்தியாவின் பண்பாடு, வேளாண்மை மற்றும் மக்கள் வாழ்வாதாரத்தில் கங்கை நதி மிக முக்கியப் பங்காற்றுகிறது.","difficulty":"medium","topic":"தேசியச் சின்னங்கள்"},{"id":950,"subject":"gk","testNumber":10,"question":"இந்தியாவின் 'தேசிய நீர்வாழ் விலங்கு' (National Aquatic Animal) எது?","options":["காரியல் முதலை","ஆலிவ் ரிட்லி ஆமை","நீலத் திமிங்கலம்","கங்கை ஆற்று ஓங்கில் (டால்பின்)"],"correctAnswer":3,"explanation":"அழிந்துவரும் உயிரினமான 'கங்கை ஆற்று ஓங்கில்' (Ganges River Dolphin / Platanista gangetica) 2010-ஆம் ஆண்டு இந்தியாவின் தேசிய நீர்வாழ் விலங்காக அறிவிக்கப்பட்டது. தூய நன்னீரில் மட்டுமே வாழும் இது, கங்கை நதியின் சுற்றுச்சூழல் ஆரோக்கியத்தைக் காட்டும் உயிரினக் குறியீடாகக் கருதப்படுகிறது.","difficulty":"medium","topic":"தேசியச் சின்னங்கள்"},{"id":951,"subject":"gk","testNumber":10,"question":"இந்திய அரசால் 2010-ஆம் ஆண்டு 'தேசிய பாரம்பரிய விலங்காக' (National Heritage Animal) அறிவிக்கப்பட்டது எது?","options":["இந்திய யானை","ஆசியச் சிங்கம்","ஒற்றைக் கொம்பு காண்டாமிருகம்","பனிச் சிறுத்தை"],"correctAnswer":0,"explanation":"இந்தியாவின் பண்பாடு, வரலாறு மற்றும் காடுகளின் சூழலியல் சமநிலையில் முக்கியப் பங்கு வகிக்கும் 'இந்திய யானை' (Elephas maximus) 2010 அக்டோபரில் இந்தியாவின் தேசிய பாரம்பரிய விலங்காக அறிவிக்கப்பட்டது. யானைகளைப் பாதுகாக்க 1992-இல் 'யானைகள் பாதுகாப்புத் திட்டம்' தொடங்கப்பட்டது.","difficulty":"medium","topic":"தேசியச் சின்னங்கள்"},{"id":952,"subject":"gk","testNumber":10,"question":"தமிழ்நாடு அரசின் அதிகாரப்பூர்வ மாநிலச் சின்னத்தில் (State Emblem) இடம்பெற்றுள்ள புகழ்பெற்ற கோயில் கோபுரம் எது?","options":["ஸ்ரீவில்லிபுத்தூர் ஆண்டாள் கோயில் கோபுரம்","மதுரை மீனாட்சியம்மன் கோயில் கோபுரம்","தஞ்சாவூர் பெரிய கோயில் கோபுரம்","திருவரங்கம் அரங்கநாதர் கோயில் கோபுரம்"],"correctAnswer":0,"explanation":"தமிழ்நாடு அரசின் மாநிலச் சின்னத்தில் விருதுநகர் மாவட்டத்தில் உள்ள ஸ்ரீவில்லிபுத்தூர் ஆண்டாள் கோயிலின் 11 நிலை இராஜகோபுரம் இடம்பெற்றுள்ளது. இதைச் சுற்றி இரு இந்திய தேசியக் கொடிகளும், மேலே அசோகத் தூண் சிங்கச் சின்னமும், கீழே 'வாய்மையே வெல்லும்' என்ற வாசகமும் பொறிக்கப்பட்டுள்ளன. இதனை ஓவியர் ஆர். கிருஷ்ணராவ் 1949-இல் வடிவமைத்தார்.","difficulty":"easy","topic":"தமிழ்நாடு மாநிலச் சின்னங்கள்"},{"id":953,"subject":"gk","testNumber":10,"question":"தமிழ்நாட்டின் மாநில விலங்கான 'வரையாடு' (Nilgiri Tahr) எந்த மலைத்தொடரில் மட்டுமே காணப்படும் அரியவகை உயிரினமாகும்?","options":["சாத்புரா மலை","விந்திய மலை","கிழக்குத் தொடர்ச்சி மலை","மேற்குத் தொடர்ச்சி மலை"],"correctAnswer":3,"explanation":"தமிழ்நாட்டின் மாநில விலங்கான நீலகிரி வரையாடு (Nilgiritragus hylocrius) மேற்குத் தொடர்ச்சி மலையின் உயரமான புல்வெளி மற்றும் பாறைப் பகுதிகளில் மட்டுமே வாழும் அகணிய உயிரினமாகும். சங்க இலக்கியங்களில் இது 'வருடை' எனக் குறிப்பிடப்பட்டுள்ளது.","difficulty":"medium","topic":"தமிழ்நாடு மாநிலச் சின்னங்கள்"},{"id":954,"subject":"gk","testNumber":10,"question":"தமிழ்நாட்டின் அதிகாரப்பூர்வ மாநிலப் பறவை (State Bird) எது?","options":["மரகதப் புறா","மயில்","இருவாச்சிப் பறவை","நீலக்கழுத்துப் பறவை"],"correctAnswer":0,"explanation":"தமிழ்நாட்டின் மாநிலப் பறவை 'மரகதப் புறா' (Emerald Dove / Chalcophaps indica) ஆகும். இதன் இறக்கைகள் பச்சை மரகத நிறத்தில் ஒளிர்வதால் இப்பெயர் பெற்றது. இது பெரும்பாலும் வெப்பமண்டலப் பசுமைமாறாக் காடுகளிலும் மூங்கில் காடுகளிலும் வசிக்கிறது.","difficulty":"easy","topic":"தமிழ்நாடு மாநிலச் சின்னங்கள்"},{"id":955,"subject":"gk","testNumber":10,"question":"தமிழ்நாட்டின் மாநில மலர் மற்றும் மாநில மரம் ஆகியவை முறையே எவை?","options":["மல்லிகை மலர் மற்றும் தென்னை மரம்","தாமரை மலர் மற்றும் ஆலமரம்","செங்காந்தள் மலர் மற்றும் பனை மரம்","குறிஞ்சி மலர் மற்றும் வேப்ப மரம்"],"correctAnswer":2,"explanation":"தமிழ்நாட்டின் மாநில மலர் 'செங்காந்தள் மலர்' (Gloriosa superba / கார்த்திகைப் பூ) ஆகும்; இதனைச் சங்க இலக்கியம் மிகச் சிறப்பித்துக் கூறுகிறது. தமிழ்நாட்டின் மாநில மரம் 'பனை மரம்' (Borassus flabellifer) ஆகும்; இதன் அனைத்துப் பாகங்களும் மனிதனுக்குப் பயன்படுவதால் 'கற்பகத் தரு' எனப் போற்றப்படுகிறது.","difficulty":"easy","topic":"தமிழ்நாடு மாநிலச் சின்னங்கள்"},{"id":956,"subject":"gk","testNumber":10,"question":"தமிழ்நாட்டின் மாநிலப் பழம் மற்றும் மாநில விளையாட்டு ஆகியவை முறையே எவை?","options":["வாழைப்பழம் மற்றும் கோ-கோ","மாம்பழம் மற்றும் சிலம்பம்","கொய்யாப்பழம் மற்றும் வாலிபால்","பலாப்பழம் மற்றும் கபடி"],"correctAnswer":3,"explanation":"தமிழ்நாட்டின் மாநிலப் பழம் 'பலாப்பழம்' (Jackfruit) ஆகும்; முக்கனிகளில் ஒன்றான இது பண்ருட்டி பகுதியில் மிகுதியாக விளைகிறது. தமிழ்நாட்டின் மாநில விளையாட்டு 'கபடி' (சடுகுடு) ஆகும்; இது தமிழர்களின் பாரம்பரிய வீர விளையாட்டாகும்.","difficulty":"easy","topic":"தமிழ்நாடு மாநிலச் சின்னங்கள்"},{"id":957,"subject":"gk","testNumber":10,"question":"தமிழ்நாட்டின் மாநிலப் பாடலான 'தமிழ்த்தாய் வாழ்த்து' ('நீராருங் கடலுடுத்த...') பாடலை இயற்றியவர் மற்றும் அதற்கு இசையமைத்தவர் யார்?","options":["மகாகவி பாரதியார் மற்றும் இளையராஜா","நாமக்கல் கவிஞர் மற்றும் ஜி. இராமநாதன்","பாவேந்தர் பாரதிதாசன் மற்றும் கே.வி. மகாதேவன்","மனோன்மணியம் பெ. சுந்தரனார் மற்றும் எம்.எஸ். விஸ்வநாதன்"],"correctAnswer":3,"explanation":"தமிழ்த்தாய் வாழ்த்துப் பாடல் மனோன்மணியம் பெ. சுந்தரனார் 1891-இல் எழுதிய 'மனோன்மணியம்' என்ற நாடக நூலிலிருந்து எடுக்கப்பட்டது. இதற்கு மெல்லிசை மன்னர் எம்.எஸ். விஸ்வநாதன் மோகன இராகத்தில் இசையமைத்தார். இதனைப் பாடும் கால அளவு 55 வினாடிகள் ஆகும்.","difficulty":"medium","topic":"தமிழ்நாடு மாநிலச் சின்னங்கள்"},{"id":958,"subject":"gk","testNumber":10,"question":"தமிழ்நாடு அரசால் 2019-ஆம் ஆண்டு 'மாநில வண்ணத்துப்பூச்சியாக' (State Butterfly) அறிவிக்கப்பட்டது எது?","options":["நீல மோர்மன் (Blue Mormon)","தமிழ் மறவன் (Tamil Yeoman)","மலபார் மயில் (Malabar Banded Peacock)","தெற்கு பறவை இறக்கை (Southern Birdwing)"],"correctAnswer":1,"explanation":"மேற்குத் தொடர்ச்சி மலைப் பகுதிகளில் வாழும் 'தமிழ் மறவன்' (Tamil Yeoman / Cirrochroa thais) என்ற வண்ணத்துப்பூச்சி 2019-ஆம் ஆண்டு தமிழ்நாட்டின் மாநில வண்ணத்துப்பூச்சியாக அறிவிக்கப்பட்டது. இதன் மூலம் மாநில வண்ணத்துப்பூச்சியை அறிவித்த இந்தியாவின் ஐந்தாவது மாநிலம் தமிழ்நாடு ஆனது.","difficulty":"medium","topic":"தமிழ்நாடு மாநிலச் சின்னங்கள்"},{"id":959,"subject":"gk","testNumber":10,"question":"இந்திய விண்வெளி ஆராய்ச்சி நிறுவனம் (ISRO) எந்த ஆண்டு நிறுவப்பட்டது மற்றும் அதன் தலைமையகம் எங்கு அமைந்துள்ளது?","options":["1969 — பெங்களூரு","1972 — ஹைதராபாத்","1969 — ஸ்ரீஹரிகோட்டா","1962 — திருவனந்தபுரம்"],"correctAnswer":0,"explanation":"இந்திய விண்வெளி ஆராய்ச்சி நிறுவனம் (ISRO) 1969 ஆகஸ்ட் 15-ஆம் தேதி நிறுவப்பட்டது. இதன் தலைமையகம் கர்நாடக மாநிலத்தின் பெங்களூருவில் ('அந்தரிக்ஷ் பவன்') அமைந்துள்ளது. ஆந்திரப் பிரதேசத்தின் ஸ்ரீஹரிகோட்டாவில் சதீஷ் தவான் விண்வெளி ஏவுதளம் அமைந்துள்ளது.","difficulty":"easy","topic":"இந்திய விண்வெளித் திட்டம்"},{"id":960,"subject":"gk","testNumber":10,"question":"'இந்திய விண்வெளித் திட்டத்தின் தந்தை' (Father of Indian Space Programme) என்று போற்றப்படுபவர் யார்?","options":["டாக்டர் சதீஷ் தவான்","டாக்டர் விக்ரம் சாராபாய்","டாக்டர் யு.ஆர். ராவ்","டாக்டர் கே. சிவன்"],"correctAnswer":1,"explanation":"டாக்டர் விக்ரம் அம்பாலால் சாராபாய் 1962-இல் இந்திய தேசிய விண்வெளி ஆராய்ச்சிக் குழுவையும் (INCOSPAR), 1969-இல் இஸ்ரோவையும் (ISRO) உருவாக்க முன்னின்றார். இதனால் இவர் 'இந்திய விண்வெளித் திட்டத்தின் தந்தை' எனப் போற்றப்படுகிறார். இவரது நினைவாகத் திருவனந்தபுரத்தில் விக்ரம் சாராபாய் விண்வெளி மையம் உள்ளது.","difficulty":"easy","topic":"இந்திய விண்வெளித் திட்டம்"},{"id":961,"subject":"gk","testNumber":10,"question":"இந்தியா உருவாக்கிய முதல் செயற்கைக்கோளான 'ஆரியபட்டா' (Aryabhata) எந்த ஆண்டு விண்ணில் ஏவப்பட்டது?","options":["1980 ஜூலை 18","1979 ஜூன் 7","1975 ஏப்ரல் 19","1983 ஆகஸ்ட் 30"],"correctAnswer":2,"explanation":"பண்டைய இந்தியக் கணித மற்றும் வானியல் அறிஞரான ஆரியபட்டரின் நினைவாகப் பெயரிடப்பட்ட 'ஆரியபட்டா' செயற்கைக்கோள் 1975 ஏப்ரல் 19-ஆம் தேதி சோவியத் ஒன்றியத்தின் (ரஷ்யா) காபுஸ்டின் யார் ஏவுதளத்திலிருந்து காஸ்மாஸ்-3M ஏவூர்தி மூலம் விண்ணில் ஏவப்பட்டது.","difficulty":"medium","topic":"இந்திய விண்வெளித் திட்டம்"},{"id":962,"subject":"gk","testNumber":10,"question":"நிலவின் தென்துருவப் பகுதியில் வெற்றிகரமாகத் தரையிறங்கிய உலகின் முதல் நாடு என்ற பெருமையை இந்தியாவிற்குப் பெற்றுத் தந்த விண்கலம் எது?","options":["ககன்யான்","சந்திரயான்-2","சந்திரயான்-1","சந்திரயான்-3"],"correctAnswer":3,"explanation":"இஸ்ரோவின் சந்திரயான்-3 விண்கலத்தின் 'விக்ரம்' லேண்டர் 2023 ஆகஸ்ட் 23-ஆம் தேதி நிலவின் தென்துருவப் பகுதியில் வெற்றிகரமாகத் தரையிறங்கியது. இதிலிருந்த 'பிரக்யான்' ரோவர் நிலவின் மேற்பரப்பை ஆய்வு செய்தது. இதன் நினைவாக ஆகஸ்ட் 23 'தேசிய விண்வெளி தினமாக' அறிவிக்கப்பட்டுள்ளது.","difficulty":"easy","topic":"இந்திய விண்வெளித் திட்டம்"},{"id":963,"subject":"gk","testNumber":10,"question":"செவ்வாய் கிரகத்தின் சுற்றுப்பாதையை முதல் முயற்சியிலேயே வெற்றிகரமாக அடைந்த ஆசியாவின் முதல் விண்கலமான 'மங்கள்யான்' (MOM) எந்த ஏவூர்தி மூலம் ஏவப்பட்டது?","options":["PSLV-C25","PSLV-C11","GSLV Mk-III","SLV-3"],"correctAnswer":0,"explanation":"இந்தியாவின் முதல் செவ்வாய்க் கோள் ஆய்வு விண்கலமான 'மங்கள்யான்' (Mars Orbiter Mission) 2013 நவம்பர் 5-ஆம் தேதி PSLV-C25 ஏவூர்தி மூலம் விண்ணில் ஏவப்பட்டது. இது 2014 செப்டம்பர் 24-ஆம் தேதி செவ்வாயின் சுற்றுப்பாதையை வெற்றிகரமாக அடைந்து வரலாறு படைத்தது.","difficulty":"hard","topic":"இந்திய விண்வெளித் திட்டம்"},{"id":964,"subject":"gk","testNumber":10,"question":"சூரியனை ஆய்வு செய்வதற்காக இஸ்ரோவால் 2023 செப்டம்பர் 2-ஆம் தேதி விண்ணில் ஏவப்பட்ட இந்தியாவின் முதல் சூரிய ஆய்வு விண்கலம் எது?","options":["சூர்யா-1","ஆஸ்ட்ரோசாட்","ஆதித்யா-L1","பாஸ்கரா-2"],"correctAnswer":2,"explanation":"சூரியனின் வெளிப்புற அடுக்குகள் மற்றும் சூரியப் புயல்களை ஆய்வு செய்ய இஸ்ரோவால் 2023 செப்டம்பர் 2-இல் PSLV-C57 ஏவூர்தி மூலம் 'ஆதித்யா-L1' விண்கலம் ஏவப்பட்டது. இது பூமியிலிருந்து சுமார் 15 லட்சம் கி.மீ தொலைவில் உள்ள சூரியன்-பூமி லெக்ராஞ்சியன் புள்ளி-1 (L1) சுற்றுப்பாதையில் நிலைநிறுத்தப்பட்டுள்ளது.","difficulty":"medium","topic":"இந்திய விண்வெளித் திட்டம்"},{"id":965,"subject":"gk","testNumber":10,"question":"ஒருங்கிணைந்த வழிகாட்டப்பட்ட ஏவுகணை வளர்ச்சித் திட்டத்திற்குத் (IGMDP) தலைமை தாங்கி 'இந்திய ஏவுகணை மனிதர்' எனப் போற்றப்படுபவர் யார்?","options":["டாக்டர் மயில்சாமி அண்ணாதுரை","டாக்டர் கஸ்தூரிரங்கன்","டாக்டர் ஏ.பி.ஜே. அப்துல் கலாம்","டாக்டர் மாதவன் நாயர்"],"correctAnswer":2,"explanation":"அக்னி, பிருத்வி, திரிசூல், நாக் மற்றும் ஆகாஷ் ஆகிய ஏவுகணைகளை உருவாக்கிய ஒருங்கிணைந்த ஏவுகணைத் திட்டத்திற்குத் தலைமை தாங்கிய டாக்டர் ஏ.பி.ஜே. அப்துல் கலாம் 'இந்திய ஏவுகணை மனிதர்' என அழைக்கப்படுகிறார். இவர் 1997-இல் பாரத ரத்னா விருது பெற்றார் மற்றும் 2002–2007 வரை இந்தியாவின் 11-வது குடியரசுத் தலைவராகப் பணியாற்றினார்.","difficulty":"easy","topic":"இந்திய விண்வெளித் திட்டம்"},{"id":966,"subject":"gk","testNumber":10,"question":"'இந்திய அணுசக்தித் திட்டத்தின் தந்தை' (Father of Indian Nuclear Programme) என்று அழைக்கப்படுபவர் யார்?","options":["டாக்டர் பி.கே. ஐயங்கார்","டாக்டர் அனில் ககோட்கர்","டாக்டர் இராஜா ராமண்ணா","டாக்டர் ஹோமி ஜஹாங்கீர் பாபா"],"correctAnswer":3,"explanation":"டாக்டர் ஹோமி ஜஹாங்கீர் பாபா 1948-இல் இந்திய அணுசக்தி ஆணையம் நிறுவப்படக் காரணமாக இருந்து அதன் முதல் தலைவராகப் பணியாற்றினார். மும்பையில் டாடா அடிப்படை ஆராய்ச்சி நிறுவனத்தையும் (TIFR), டிராம்பே அணுசக்தி நிறுவனத்தையும் (தற்போது BARC) உருவாக்கிய இவர் 'இந்திய அணுசக்தித் திட்டத்தின் தந்தை' எனப் போற்றப்படுகிறார்.","difficulty":"medium","topic":"இந்திய அணுசக்தி"},{"id":967,"subject":"gk","testNumber":10,"question":"தமிழ்நாட்டில் அமைந்துள்ள இந்தியாவின் இரு முக்கிய அணுமின் நிலையங்கள் மற்றும் அவை அமைந்துள்ள மாவட்டங்களின் சரியான இணை எது?","options":["தாராப்பூர் (செங்கல்பட்டு) மற்றும் கூடங்குளம் (கன்னியாகுமரி)","கல்பாக்கம் (காஞ்சிபுரம்) மற்றும் கைகா (திருநெல்வேலி)","நரோரா (வேலூர்) மற்றும் கூடங்குளம் (தூத்துக்குடி)","கல்பாக்கம் (செங்கல்பட்டு) மற்றும் கூடங்குளம் (திருநெல்வேலி)"],"correctAnswer":3,"explanation":"தமிழ்நாட்டில் செங்கல்பட்டு மாவட்டத்தில் கல்பாக்கம் (சென்னை அணுமின் நிலையம் - MAPS) மற்றும் திருநெல்வேலி மாவட்டத்தில் கூடங்குளம் அணுமின் நிலையம் (KKNPP - ரஷ்யா உதவியுடன் அமைக்கப்பட்டது) ஆகிய இரு முக்கிய அணுமின் நிலையங்கள் செயல்படுகின்றன. தாராப்பூர் மகாராஷ்டிராவிலும், கைகா கர்நாடகாவிலும் உள்ளன.","difficulty":"medium","topic":"இந்திய அணுசக்தி"},{"id":968,"subject":"gk","testNumber":10,"question":"இந்தியாவின் மிக உயர்ந்த குடிமக்கள் விருதான 'பாரத ரத்னா' 1954-ஆம் ஆண்டு முதன்முதலில் யாருக்கு வழங்கப்பட்டது?","options":["மௌலானா ஆசாத், விஸ்வேஸ்வரய்யா, பி.சி. ராய்","சி. இராஜகோபாலாச்சாரி, டாக்டர் எஸ். இராதாகிருஷ்ணன், சர் சி.வி. ராமன்","மகாத்மா காந்தி, இரவீந்திரநாத் தாகூர், நேதாஜி சுபாஷ் சந்திர போஸ்","ஜவஹர்லால் நேரு, சர்தார் வல்லபாய் படேல், டாக்டர் அம்பேத்கர்"],"correctAnswer":1,"explanation":"இந்தியாவின் மிக உயர்ந்த குடிமக்கள் விருதான 'பாரத ரத்னா' 1954-ஆம் ஆண்டு அறிமுகப்படுத்தப்பட்டது. முதல் ஆண்டில் சுதந்திர இந்தியாவின் முதல் இந்திய ஆளுநர் சி. இராஜகோபாலாச்சாரி, தத்துவ அறிஞர் டாக்டர் எஸ். இராதாகிருஷ்ணன் மற்றும் இயற்பியல் அறிஞர் சர் சி.வி. ராமன் ஆகிய மூவருக்கும் இவ்விருது வழங்கப்பட்டது.","difficulty":"medium","topic":"விருதுகள்"},{"id":969,"subject":"gk","testNumber":10,"question":"பின்வரும் நோபல் பரிசு பெற்ற இந்தியர்கள் மற்றும் அவர்கள் பரிசு பெற்ற துறைகளுள் தவறாகப் பொருந்தியுள்ளது எது?","options":["இரவீந்திரநாத் தாகூர் — இலக்கியம் (1913)","அமர்த்தியா சென் — சமாதானம் (1998)","அன்னை தெரசா — அமைதி (1979)","சர் சி.வி. ராமன் — இயற்பியல் (1930)"],"correctAnswer":1,"explanation":"பேராசிரியர் அமர்த்தியா சென் 1998-ஆம் ஆண்டு நலப் பொருளாதாரம் (Welfare Economics) குறித்த ஆய்வுக்காக 'பொருளாதாரத்திற்கான' நோபல் பரிசைப் பெற்றார்; அமைதிக்கான பரிசு அல்ல. இரவீந்திரநாத் தாகூர் (1913, இலக்கியம்), சர் சி.வி. ராமன் (1930, இயற்பியல்), அன்னை தெரசா (1979, அமைதி) மற்றும் கைலாஷ் சத்யார்த்தி (2014, அமைதி) ஆகியோர் சரியாகப் பொருந்தியுள்ளனர்.","difficulty":"hard","topic":"விருதுகள்"},{"id":970,"subject":"gk","testNumber":10,"question":"இந்தியத் திரைப்படத் துறையின் மிக உயர்ந்த விருதான 'தாதாசாகேப் பால்கே விருது' 1969-ஆம் ஆண்டு முதன்முதலில் யாருக்கு வழங்கப்பட்டது?","options":["சிவாஜி கணேசன்","சத்யஜித் ரே","பிருத்விராஜ் கபூர்","தேவிகா ராணி"],"correctAnswer":3,"explanation":"'இந்தியத் திரைப்படத் துறையின் தந்தை' எனப்படும் தாதாசாகேப் பால்கேவின் நினைவாக 1969-இல் தொடங்கப்பட்ட தாதாசாகேப் பால்கே விருதை முதன்முதலில் பெற்றவர் நடிகை தேவிகா ராணி ஆவார். தமிழ்நாட்டைச் சேர்ந்த சிவாஜி கணேசன் (1996), கே. பாலசந்தர் (2010), இரசினிகாந்த் (2019) ஆகியோரும் இவ்விருதைப் பெற்றுள்ளனர்.","difficulty":"medium","topic":"விருதுகள்"},{"id":971,"subject":"gk","testNumber":10,"question":"இந்திய இலக்கியத் துறையின் மிக உயர்ந்த விருதான 'ஞானபீட விருது' (Jnanpith Award) பெற்ற தமிழ் எழுத்தாளர்கள் யார்?","options":["மு. வரதராசனார் மற்றும் கண்ணதாசன்","அகிலன் மற்றும் ஜெயகாந்தன்","கல்கி மற்றும் புதுமைப்பித்தன்","கி. ராஜநாராயணன் மற்றும் சுஜாதா"],"correctAnswer":1,"explanation":"இந்திய அரசியலமைப்பின் 8-வது அட்டவணை மொழிகளில் சிறந்த இலக்கியப் படைப்பிற்காக வழங்கப்படும் 'ஞானபீட விருதை' தமிழில் இருவர் பெற்றுள்ளனர். 1975-இல் எழுத்தாளர் அகிலன் ('சித்திரப்பாவை' நாவலுக்காக) மற்றும் 2002-இல் எழுத்தாளர் ஜெயகாந்தன் (ஒட்டுமொத்த தமிழ் இலக்கியப் பங்களிப்பிற்காக) இவ்விருதைப் பெற்றனர்.","difficulty":"medium","topic":"விருதுகள்"},{"id":972,"subject":"gk","testNumber":10,"question":"ஐக்கிய நாடுகள் சபை (UN) மற்றும் ஐ.நா. சிறுவர் நிதியம் (UNICEF) ஆகிய இரு அமைப்புகளின் தலைமையிடங்களும் எந்த நகரத்தில் அமைந்துள்ளன?","options":["ஜெனீவா (சுவிட்சர்லாந்து)","நியூயார்க் (அமெரிக்கா)","லண்டன் (இங்கிலாந்து)","வாஷிங்டன் டி.சி. (அமெரிக்கா)"],"correctAnswer":1,"explanation":"ஐக்கிய நாடுகள் சபை (United Nations - 1945) மற்றும் ஐக்கிய நாடுகள் சிறுவர் நிதியம் (UNICEF - 1946) ஆகிய இரண்டின் தலைமையிடங்களும் அமெரிக்காவின் நியூயார்க் நகரில் அமைந்துள்ளன. ஐ.நா.வின் ஆறு முக்கிய அங்கங்களில் சர்வதேச நீதிமன்றத்தின் தலைமையகம் மட்டும் நெதர்லாந்தின் தி ஹேக் நகரில் உள்ளது.","difficulty":"medium","topic":"உலக அமைப்புகள்"},{"id":973,"subject":"gk","testNumber":10,"question":"உலக அமைப்புகள் மற்றும் அவற்றின் தலைமையிடங்களைச் சரியாகப் பொருத்துக.\n(a) WHO (உலக சுகாதார நிறுவனம்) - 1. ரோம்\n(b) UNESCO (யுனெஸ்கோ) - 2. காத்மாண்டு\n(c) FAO (உணவு & வேளாண் அமைப்பு) - 3. ஜெனீவா\n(d) SAARC (சார்க் அமைப்பு) - 4. பாரிஸ்","options":["a-2, b-4, c-1, d-3","a-3, b-1, c-4, d-2","a-3, b-4, c-1, d-2","a-4, b-3, c-1, d-2"],"correctAnswer":2,"explanation":"உலக சுகாதார நிறுவனம் (WHO) ஜெனீவாவிலும் (சுவிட்சர்லாந்து), யுனெஸ்கோ (UNESCO) பாரிஸிலும் (பிரான்ஸ்), உணவு மற்றும் வேளாண்மை அமைப்பு (FAO) ரோமிலும் (இத்தாலி), தெற்காசிய பிராந்திய ஒத்துழைப்பு அமைப்பு (SAARC) காத்மாண்டுவிலும் (நேபாளம்) தலைமையிடங்களைக் கொண்டுள்ளன.","difficulty":"hard","topic":"உலக அமைப்புகள்"},{"id":974,"subject":"gk","testNumber":10,"question":"தெற்காசிய நாடுகளின் பிராந்திய ஒத்துழைப்பு அமைப்பான 'சார்க்' (SAARC) 1985-இல் எங்கு நிறுவப்பட்டது மற்றும் இதில் உள்ள உறுப்பு நாடுகளின் எண்ணிக்கை எவ்வளவு?","options":["புதுடெல்லி — 7 நாடுகள்","கொழும்பு — 10 நாடுகள்","டாக்கா — 8 நாடுகள்","காத்மாண்டு — 6 நாடுகள்"],"correctAnswer":2,"explanation":"சார்க் (SAARC - South Asian Association for Regional Cooperation) அமைப்பு 1985 டிசம்பர் 8-ஆம் தேதி வங்கதேசத்தின் டாக்காவில் நிறுவப்பட்டது; இதன் தலைமையகம் நேபாளத்தின் காத்மாண்டுவில் உள்ளது. இந்தியா, பாகிஸ்தான், வங்கதேசம், இலங்கை, நேபாளம், பூட்டான், மாலத்தீவுகள் மற்றும் ஆப்கானிஸ்தான் (2007-இல் இணைந்தது) என மொத்தம் 8 உறுப்பு நாடுகள் உள்ளன.","difficulty":"hard","topic":"உலக அமைப்புகள்"},{"id":975,"subject":"gk","testNumber":10,"question":"பகுப்பாய்வுப் பொறியை (Analytical Engine) வடிவமைத்து 'கணினியின் தந்தை' (Father of Computer) என்று போற்றப்படுபவர் யார்?","options":["ஜான் வான் நியூமன்","ஆலன் டூரிங்","சார்லஸ் பாபேஜ்","பிளேஸ் பாஸ்கல்"],"correctAnswer":2,"explanation":"இங்கிலாந்து கணிதவியலாளரான சார்லஸ் பாபேஜ் 1837-ஆம் ஆண்டில் நவீன கணினியின் அடிப்படைக் கட்டமைப்பைக் கொண்ட 'பகுப்பாய்வுப் பொறியை' (Analytical Engine) வடிவமைத்தார். இதனால் இவர் 'கணினியின் தந்தை' என அழைக்கப்படுகிறார். முதல் கணினி நிரலராக அடா லவ்லேஸ் போற்றப்படுகிறார்.","difficulty":"easy","topic":"அடிப்படை கணினி அறிவியல்"},{"id":976,"subject":"gk","testNumber":10,"question":"பொருத்துக: கணினி தலைமுறைகள் மற்றும் அவற்றில் பயன்படுத்தப்பட்ட முக்கிய மின்னணுத் தொழில்நுட்பங்கள்.\n(a) முதல் தலைமுறை - 1. ஒருங்கிணைந்த சுற்றுகள் (IC)\n(b) இரண்டாம் தலைமுறை - 2. நுண்செயலி (Microprocessor)\n(c) மூன்றாம் தலைமுறை - 3. வெற்றிடக் குழாய்கள் (Vacuum Tubes)\n(d) நான்காம் தலைமுறை - 4. டிரான்சிஸ்டர்கள் (Transistors)","options":["a-3, b-4, c-2, d-1","a-3, b-1, c-4, d-2","a-3, b-4, c-1, d-2","a-4, b-3, c-1, d-2"],"correctAnswer":2,"explanation":"முதல் தலைமுறைக் கணினிகளில் வெற்றிடக் குழாய்களும் (Vacuum Tubes), இரண்டாம் தலைமுறையில் டிரான்சிஸ்டர்களும், மூன்றாம் தலைமுறையில் ஒருங்கிணைந்த சுற்றுகளும் (Integrated Circuits - IC), நான்காம் தலைமுறையில் மிகப் பெரிய அளவிலான ஒருங்கிணைந்த நுண்செயலிகளும் (VLSI Microprocessors) பயன்படுத்தப்பட்டன.","difficulty":"hard","topic":"கணினி தலைமுறைகள்"},{"id":977,"subject":"gk","testNumber":10,"question":"செயற்கை நுண்ணறிவு (Artificial Intelligence) மற்றும் மீப்பேரளவு ஒருங்கிணைந்த சுற்று (ULSI) ஆகியவை எந்தத் தலைமுறை கணினிகளின் அடிப்படைத் தொழில்நுட்பமாகும்?","options":["மூன்றாம் தலைமுறை","இரண்டாம் தலைமுறை","ஐந்தாம் தலைமுறை","நான்காம் தலைமுறை"],"correctAnswer":2,"explanation":"ஐந்தாம் தலைமுறைக் கணினிகள் (Fifth Generation Computers) செயற்கை நுண்ணறிவு (AI), இயற்கை மொழிச் செயலாக்கம் (NLP) மற்றும் ULSI (Ultra Large Scale Integration) தொழில்நுட்பத்தை அடிப்படையாகக் கொண்டவை. மனிதர்களைப் போலச் சிந்தித்து முடிவெடுக்கும் திறன் கொண்ட கணினிகளை உருவாக்குவதே இதன் நோக்கமாகும்.","difficulty":"easy","topic":"கணினி தலைமுறைகள்"},{"id":978,"subject":"gk","testNumber":10,"question":"பின்வருவனவற்றுள் எது கணினியின் 'உள்ளீட்டுச் சாதனம்' (Input Device) அல்ல?","options":["பட்டைக் குறியீடு படிப்பான் (Barcode Reader)","வரைவி (Plotter)","ஒளிப் பேனா (Light Pen)","வருடி (Scanner)"],"correctAnswer":1,"explanation":"வரைவி (Plotter) என்பது பொறியியல் வரைபடங்கள், கட்டட வடிவமைப்புகள் போன்ற பெரிய அளவிலான படங்களைத் தாளில் அச்சிடும் ஒரு 'வெளியீட்டுச் சாதனம்' (Output Device) ஆகும். வருடி (Scanner), ஒளிப் பேனா (Light Pen) மற்றும் பார்கோடு ரீடர் ஆகியவை கணினிக்குத் தரவுகளை வழங்கும் உள்ளீட்டுச் சாதனங்கள் ஆகும்.","difficulty":"medium","topic":"உள்ளீட்டு & வெளியீட்டு சாதனங்கள்"},{"id":979,"subject":"gk","testNumber":10,"question":"'கணினியின் மூளை' என அழைக்கப்படும் மையச் செயலகத்தின் (CPU) இரு முக்கியப் பகுதிகள் எவை?","options":["வன்வட்டு மற்றும் தாய்ப்பலகை","RAM மற்றும் ROM","கணிதத் தர்க்க அலகு (ALU) மற்றும் கட்டுப்பாட்டு அலகு (CU)","உள்ளீட்டு அலகு மற்றும் வெளியீட்டு அலகு"],"correctAnswer":2,"explanation":"மையச் செயலகம் (CPU - Central Processing Unit) கணினியின் மூளையாகச் செயல்படுகிறது. இதன் இரு முக்கியப் பகுதிகள்: (1) கணிதத் தர்க்க அலகு (ALU - Arithmetic Logic Unit) - அனைத்துக் கூட்டல், கழித்தல் மற்றும் தர்க்க ஒப்பீடுகளைச் செய்யும்; (2) கட்டுப்பாட்டு அலகு (CU - Control Unit) - கணினியின் அனைத்துப் பாகங்களின் செயல்பாடுகளையும் ஒருங்கிணைத்துக் கட்டுப்படுத்தும்.","difficulty":"easy","topic":"கணினி வன்பொருள்"},{"id":980,"subject":"gk","testNumber":10,"question":"மின்சாரம் துண்டிக்கப்பட்டவுடன் தன்னுள் சேமிக்கப்பட்ட தரவுகளை இழந்துவிடும் தற்காலிக முதன்மை நினைவகம் (Volatile Memory) எது?","options":["SSD","RAM","ROM","Hard Disk"],"correctAnswer":1,"explanation":"RAM (Random Access Memory) என்பது கணினியின் தற்காலிக (அழியும் தன்மையுடைய - Volatile) முதன்மை நினைவகமாகும். கணினி இயங்கும்போது பயன்பாட்டிலுள்ள நிரல்களையும் தரவுகளையும் இது சேமித்து வைக்கும்; மின்சாரம் நிறுத்தப்பட்டவுடன் இதில் உள்ள தரவுகள் அனைத்தும் அழிந்துவிடும்.","difficulty":"easy","topic":"கணினி நினைவகம்"},{"id":981,"subject":"gk","testNumber":10,"question":"கணினியைத் தொடங்கும் (Booting) அடிப்படைக் கட்டளைகளை நிரந்தரமாகச் சேமித்து வைக்கும் அழியா நினைவகம் (Non-Volatile Memory) எது?","options":["SRAM (Static RAM)","DRAM (Dynamic RAM)","ROM (Read Only Memory)","பதிவகம் (Register)"],"correctAnswer":2,"explanation":"ROM (Read Only Memory) என்பது மின்சாரம் துண்டிக்கப்பட்டாலும் தரவுகளை இழக்காத அழியா நினைவகம் (Non-Volatile Memory) ஆகும். கணினி உற்பத்தி செய்யப்படும்போதே இதனுள் கணினியைத் தொடங்கும் BIOS நிரல்கள் நிரந்தரமாகப் பதியப்படுகின்றன.","difficulty":"medium","topic":"கணினி நினைவகம்"},{"id":982,"subject":"gk","testNumber":10,"question":"மையச் செயலகத்திற்கும் (CPU) முதன்மை நினைவகத்திற்கும் (RAM) இடையே இடைத்தரகராகச் செயல்பட்டு, அடிக்கடி தேவைப்படும் தரவுகளை அதிவேகமாக வழங்கும் நினைவகம் எது?","options":["ஒளி வட்டு (Optical Disc)","காந்த நாடா (Magnetic Tape)","கேச் நினைவகம் (Cache Memory)","மெய்நிகர் நினைவகம் (Virtual Memory)"],"correctAnswer":2,"explanation":"கேச் நினைவகம் (Cache Memory) என்பது CPU-க்கும் முதன்மை நினைவகமான RAM-க்கும் இடையே அமைந்துள்ள மிக அதிவேகமான, சிறிய அளவு கொண்ட நினைவகமாகும். CPU அடிக்கடி அணுகும் தரவுகளையும் கட்டளைகளையும் இது சேமித்து வைத்து, கணினியின் செயலாக்க வேகத்தைப் பன்மடங்கு அதிகரிக்கிறது.","difficulty":"medium","topic":"கணினி நினைவகம்"},{"id":983,"subject":"gk","testNumber":10,"question":"பாரம்பரிய சுழலும் வன்வட்டுக்கு (Hard Disk Drive - HDD) மாற்றாக, நகரும் இயந்திரப் பாகங்கள் இன்றி ஃபிளாஷ் நினைவகத்தைப் பயன்படுத்தி அதிவேகமாகச் செயல்படும் சேமிப்புச் சாதனம் எது?","options":["குறுவட்டு (CD-ROM)","திடநிலை இயக்கி (SSD - Solid State Drive)","நெகிழ்வட்டு (Floppy Disk)","காந்த வட்டு (Magnetic Drum)"],"correctAnswer":1,"explanation":"SSD (Solid State Drive) என்பது சுழலும் காந்தத் தட்டுகள் போன்ற நகரும் இயந்திரப் பாகங்கள் இன்றி குறைக்கடத்தி ஃபிளாஷ் நினைவகத்தைக் கொண்டு தரவுகளைச் சேமிக்கும் இரண்டாம் நிலை நினைவகமாகும். இது வழக்கமான வன்வட்டை (HDD) விடப் பல மடங்கு வேகமாகவும், குறைந்த மின்சாரத்திலும், அதிர்வுகளால் பாதிப்படையாமலும் செயல்படுகிறது.","difficulty":"medium","topic":"கணினி நினைவகம்"},{"id":984,"subject":"gk","testNumber":10,"question":"கணினி நினைவக அளவீட்டில் '1 நிப்பிள்' (1 Nibble) மற்றும் '1 பைட்' (1 Byte) ஆகியவை முறையே எத்தனை பிட்டுகளுக்குச் (Bits) சமம்?","options":["4 பிட்டுகள் மற்றும் 8 பிட்டுகள்","2 பிட்டுகள் மற்றும் 4 பிட்டுகள்","4 பிட்டுகள் மற்றும் 16 பிட்டுகள்","8 பிட்டுகள் மற்றும் 16 பிட்டுகள்"],"correctAnswer":0,"explanation":"கணினியில் தரவின் மிகச்சிறிய அலகு 'பிட்' (Bit - Binary Digit: 0 அல்லது 1) ஆகும். 4 பிட்டுகள் சேர்ந்தது 1 நிப்பிள் (Nibble) என்றும், 8 பிட்டுகள் (அல்லது 2 நிப்பிள்கள்) சேர்ந்தது 1 பைட் (Byte) என்றும் அழைக்கப்படுகிறது.","difficulty":"medium","topic":"கணினி நினைவக அளவுகள்"},{"id":985,"subject":"gk","testNumber":10,"question":"கணினி நினைவக அளவீடுகளில் பின்வரும் சமன்பாடுகளில் எது தவறானது?","options":["1 TB = 1,000 MB","1 MB = 1,024 KB","1 KB = 1,024 Bytes","1 GB = 1,024 MB"],"correctAnswer":0,"explanation":"இரும (Binary) நினைவக அளவீட்டின்படி 1 KB = 1,024 Bytes, 1 MB = 1,024 KB, 1 GB = 1,024 MB, மற்றும் 1 TB (டெராபைட்) = 1,024 GB ஆகும். எனவே '1 TB = 1,000 MB' என்ற கூற்று தவறானதாகும் (1 TB என்பது 1,024 × 1,024 MB-க்குச் சமம்).","difficulty":"hard","topic":"கணினி நினைவக அளவுகள்"},{"id":986,"subject":"gk","testNumber":10,"question":"கணினி வன்பொருளுக்கும் பயனருக்கும் இடையே பாலமாகச் செயல்படும் 'திறந்த மூல' (Open Source) இயக்க முறைமை (Operating System) எது?","options":["மைக்ரோசாஃப்ட் விண்டோஸ் (Windows)","ஆப்பிள் ஐஓஎஸ் (iOS)","லினக்ஸ் (Linux)","ஆப்பிள் மேக்ஓஎஸ் (macOS)"],"correctAnswer":2,"explanation":"லினஸ் டோர்வால்ட்ஸ் என்பவரால் 1991-இல் உருவாக்கப்பட்ட 'லினக்ஸ்' (Linux) ஒரு இலவச மற்றும் திறந்த மூல (Open Source) இயக்க முறைமையாகும்; இதன் மூல நிரலை யார் வேண்டுமானாலும் பார்வையிட்டு மேம்படுத்தலாம். விண்டோஸ், macOS மற்றும் iOS ஆகியவை உரிமம் சார்ந்த (Proprietary) இயக்க முறைமைகள் ஆகும்.","difficulty":"medium","topic":"இயக்க முறைமைகள்"},{"id":987,"subject":"gk","testNumber":10,"question":"உயர்நிலை நிரலாக்க மொழியில் (High-Level Language) எழுதப்பட்ட முழு நிரலையும் ஒரே நேரத்தில் இயந்திர மொழியாக மாற்றும் மொழிபெயர்ப்பி எது? வரிக்கு வரி மாற்றுவது எது?","options":["தொகுப்பி (Compiler) மற்றும் வரிமொழிமாற்றி (Interpreter)","அசெம்பிளர் மற்றும் தொகுப்பி","இணைப்பி (Linker) மற்றும் ஏற்றி (Loader)","வரிமொழிமாற்றி (Interpreter) மற்றும் தொகுப்பி (Compiler)"],"correctAnswer":0,"explanation":"தொகுப்பி (Compiler) என்பது உயர்நிலை மொழியில் (எ.கா: C, C++) எழுதப்பட்ட முழு மூல நிரலையும் ஒரே நேரத்தில் இயந்திர மொழியாக மாற்றிப் பிழைகளை ஒன்றாகக் காட்டும். வரிமொழிமாற்றி (Interpreter - எ.கா: Python) நிரலை வரிக்கு வரி படித்து மொழிபெயர்த்து இயக்கும். அசெம்பிளர் அசெம்பிளி மொழியை இயந்திர மொழியாக மாற்றும்.","difficulty":"hard","topic":"நிரலாக்க மொழிகள்"},{"id":988,"subject":"gk","testNumber":10,"question":"ஒரு குறிப்பிட்ட கட்டிடம் அல்லது கல்லூரி வளாகத்திற்குள் உள்ள கணினிகளை இணைக்கும் வலைப்பின்னல் மற்றும் உலகளவில் கண்டங்களைக் கடந்து கணினிகளை இணைக்கும் வலைப்பின்னல் ஆகியவை முறையே எவை?","options":["PAN மற்றும் MAN","LAN மற்றும் WAN","WAN மற்றும் LAN","MAN மற்றும் PAN"],"correctAnswer":1,"explanation":"ஒரு சிறிய புவியியல் எல்லைக்குள் (வீடு, அலுவலகம், பள்ளி) கணினிகளை இணைப்பது குறும்பரப்பு வலைப்பின்னல் (LAN - Local Area Network) எனப்படும். நாடுகள் மற்றும் கண்டங்களைக் கடந்து மிகப் பெரிய அளவில் கணினிகளை இணைப்பது விரிபரப்பு வலைப்பின்னல் (WAN - Wide Area Network) எனப்படும்; இணையம் (Internet) WAN-க்கு சிறந்த எடுத்துக்காட்டாகும்.","difficulty":"easy","topic":"இணையம் & வலைப்பின்னல்"},{"id":989,"subject":"gk","testNumber":10,"question":"இலக்கமுறை (Digital) சமிக்கைகளை ஒப்புமை (Analog) சமிக்கைகளாகவும், ஒப்புமை சமிக்கைகளை இலக்கமுறை சமிக்கைகளாகவும் மாற்றும் வலைப்பின்னல் சாதனம் எது?","options":["திசைவி (Router)","குவியம் (Hub)","மறுஒலிப்பி (Repeater)","மோடம் (Modem)"],"correctAnswer":3,"explanation":"மோடம் (Modem - Modulator-Demodulator) என்பது தொலைபேசிக் கம்பிகள் வழியே அனுப்ப கணினியின் இலக்கமுறை சமிக்கைகளை ஒப்புமை சமிக்கைகளாக மாற்றும் (Modulation) மற்றும் பெறும்போது மீண்டும் இலக்கமுறை சமிக்கைகளாக மாற்றும் (Demodulation) சாதனமாகும். திசைவி (Router) இரு வெவ்வேறு வலைப்பின்னல்களுக்கு இடையே தரவுப் பொட்டலங்களைச் சரியான பாதையில் வழிநடத்தும்.","difficulty":"medium","topic":"இணையம் & வலைப்பின்னல்"},{"id":990,"subject":"gk","testNumber":10,"question":"இணையத்தில் இணைக்கப்பட்டுள்ள ஒவ்வொரு கணினி அல்லது சாதனத்தையும் தனித்துவமாக அடையாளம் காண வழங்கப்படும் எண் முகவரி எவ்வாறு அழைக்கப்படுகிறது?","options":["URL முகவரி","IP முகவரி","HTML குறியீடு","CPU குறியீடு"],"correctAnswer":1,"explanation":"IP முகவரி (Internet Protocol Address) என்பது இணையம் அல்லது கணினி வலைப்பின்னலில் இணைக்கப்பட்டுள்ள ஒவ்வொரு சாதனத்திற்கும் வழங்கப்படும் தனித்த எண் அடையாளமாகும். IPv4 முகவரி 32 பிட்டுகளையும் (எ.கா: 192.168.1.1), புதிய IPv6 முகவரி 128 பிட்டுகளையும் கொண்டுள்ளது.","difficulty":"medium","topic":"இணையம் & வலைப்பின்னல்"},{"id":991,"subject":"gk","testNumber":10,"question":"இணைய உலாவியில் வலைத்தளங்களுடன் பாதுகாப்பான, மறைகுறியாக்கப்பட்ட (Encrypted) தரவுப் பரிமாற்றத்தை உறுதி செய்யும் 'HTTPS' என்பதன் விரிவாக்கம் என்ன?","options":["High Transfer Text Protocol System","Hyperlink Text Transfer Path Secure","HyperText Transmission Program Service","HyperText Transfer Protocol Secure"],"correctAnswer":3,"explanation":"HTTPS என்பது 'HyperText Transfer Protocol Secure' என்பதன் சுருக்கமாகும். சாதாரண HTTP-யுடன் SSL/TLS மறைகுறியாக்கப் (Encryption) பாதுகாப்பை இணைத்து வலைத்தளத்திற்கும் பயனருக்கும் இடையிலான கடவுச்சொல், வங்கித் தகவல்கள் போன்ற தரவுகளைப் பாதுகாப்பாகப் பரிமாற இது உதவுகிறது.","difficulty":"medium","topic":"கணினி விரிவாக்கங்கள்"},{"id":992,"subject":"gk","testNumber":10,"question":"உலகளாவிய வலையில் (WWW) வலைப்பக்கங்களை (Web Pages) வடிவமைத்து உருவாக்கப் பயன்படும் 'HTML' என்பதன் சரியான விரிவாக்கம் என்ன?","options":["Hyperlink and Text Making Language","HyperText Markup Language","Home Tool Markup Language","High Text Machine Language"],"correctAnswer":1,"explanation":"HTML என்பது 'HyperText Markup Language' என்பதன் சுருக்கமாகும். டிம் பெர்னர்ஸ்-லீ உருவாக்கிய இந்தக் குறியீட்டு மொழி, இணையத்தில் உள்ள வலைப்பக்கங்களின் கட்டமைப்பு, உரைகள், படங்கள் மற்றும் மீயிணைப்புகளை (Hyperlinks) வடிவமைக்க அடிப்படை மொழியாகப் பயன்படுகிறது.","difficulty":"easy","topic":"கணினி விரிவாக்கங்கள்"},{"id":993,"subject":"gk","testNumber":10,"question":"இணையத்தில் உள்ள ஒரு குறிப்பிட்ட வலைப்பக்கம் அல்லது கோப்பின் தனித்த முகவரியைக் குறிக்கும் 'URL' என்பதன் விரிவாக்கம் என்ன?","options":["Universal Reference Link","Unified Routing Language","Uniform Retrieval Line","Uniform Resource Locator"],"correctAnswer":3,"explanation":"URL என்பது 'Uniform Resource Locator' என்பதன் சுருக்கமாகும். இணையத்தில் உள்ள ஒரு வலைப்பக்கம், படம் அல்லது ஆவணம் எங்குள்ளது என்பதைக் குறிக்கும் முழுமையான இணைய முகவரியே URL ஆகும் (எ.கா: https://www.tnpsc.gov.in).","difficulty":"medium","topic":"கணினி விரிவாக்கங்கள்"},{"id":994,"subject":"gk","testNumber":10,"question":"மனிதர்கள் எளிதில் நினைவில் கொள்ளும் டொமைன் பெயர்களை (Domain Names) கணினி புரிந்துகொள்ளும் IP முகவரிகளாக மாற்றும் 'DNS' என்பதன் விரிவாக்கம் என்ன?","options":["Direct Node Server","Data Numbering Software","Domain Name System","Digital Network Service"],"correctAnswer":2,"explanation":"DNS என்பது 'Domain Name System' என்பதன் சுருக்கமாகும். இது இணையத்தின் தொலைபேசி அகராதி (Phonebook of the Internet) போல் செயல்பட்டு, பயனர் தட்டச்சு செய்யும் வலைத்தளப் பெயர்களை (எ.கா: google.com) அவற்றுக்குரிய எண் வடிவ IP முகவரிகளாக மொழிபெயர்க்கிறது.","difficulty":"hard","topic":"கணினி விரிவாக்கங்கள்"},{"id":995,"subject":"gk","testNumber":10,"question":"பொருத்துக: கணினித் துறையில் பொதுவாகப் பயன்படுத்தப்படும் சுருக்கங்கள் மற்றும் அவற்றின் விரிவாக்கங்கள்.\n(a) PDF - 1. Universal Serial Bus\n(b) USB - 2. Graphical User Interface\n(c) GUI - 3. Portable Document Format\n(d) Wi-Fi - 4. Wireless Fidelity","options":["a-3, b-1, c-2, d-4","a-1, b-3, c-2, d-4","a-3, b-1, c-4, d-2","a-3, b-2, c-1, d-4"],"correctAnswer":0,"explanation":"PDF = Portable Document Format (ஆவணங்களை மாறாத வடிவில் பகிர), USB = Universal Serial Bus (புறச்சாதனங்களை இணைக்க), GUI = Graphical User Interface (படங்கள் மற்றும் சின்னங்கள் மூலம் கணினியை எளிதாகப் பயன்படுத்த), Wi-Fi = Wireless Fidelity (கம்பியில்லா இணைய இணைப்பு). எனவே a-3, b-1, c-2, d-4 சரியானது.","difficulty":"hard","topic":"கணினி விரிவாக்கங்கள்"},{"id":996,"subject":"gk","testNumber":10,"question":"கணினி அறிவியலில் 'BIOS' மற்றும் 'ASCII' ஆகியவற்றின் சரியான விரிவாக்கங்கள் முறையே எவை?","options":["Basic Input Output Server மற்றும் Asian Standard Code for Information Interchange","Basic Internal Operating System மற்றும் Automated Standard Code for Information Input","Binary Input Output Software மற்றும் American System Code for Internet Interchange","Basic Input Output System மற்றும் American Standard Code for Information Interchange"],"correctAnswer":3,"explanation":"BIOS (Basic Input Output System) என்பது கணினியை இயக்கியவுடன் வன்பொருட்களைச் சரிபார்த்து இயக்க முறைமையைத் தொடங்கும் மென்பொருளாகும். ASCII (American Standard Code for Information Interchange) என்பது ஆங்கில எழுத்துக்கள், எண்கள் மற்றும் குறியீடுகளைக் கணினி புரிந்துகொள்ளும் எண் மதிப்புகளாக மாற்றும் தரநிலைக் குறியீட்டு முறையாகும்.","difficulty":"hard","topic":"கணினி விரிவாக்கங்கள்"},{"id":997,"subject":"gk","testNumber":10,"question":"தொடர்புநிலைத் தரவுத்தளங்களில் (Relational Databases) தரவுகளைச் சேமிக்கவும், திருத்தவும் மற்றும் மீட்டெடுக்கவும் பயன்படும் 'SQL' என்பதன் விரிவாக்கம் என்ன?","options":["Simple Question Language","Sequential Queue Logic","Standard Query Link","Structured Query Language"],"correctAnswer":3,"explanation":"SQL என்பது 'Structured Query Language' என்பதன் சுருக்கமாகும். MySQL, Oracle, PostgreSQL போன்ற தரவுத்தள மேலாண்மை அமைப்புகளில் (RDBMS) அட்டவணைகளை உருவாக்கவும், தரவுகளை உள்ளிடவும், புதுப்பிக்கவும், தேடி எடுக்கவும் பயன்படும் தரநிலை வினவல் மொழி இதுவாகும்.","difficulty":"medium","topic":"கணினி விரிவாக்கங்கள்"},{"id":998,"subject":"gk","testNumber":10,"question":"அங்கீகரிக்கப்படாத வெளியாள் அணுகலிலிருந்து கணினி மற்றும் வலைப்பின்னலைப் பாதுகாக்கும் பாதுகாப்பு அரண் (Security System) எவ்வாறு அழைக்கப்படுகிறது?","options":["தேடுபொறி (Search Engine)","வலை உலாவி (Web Browser)","ஃபயர்வால் (Firewall)","குக்கீஸ் (Cookies)"],"correctAnswer":2,"explanation":"ஃபயர்வால் (Firewall - தீச்சுவர்) என்பது ஒரு கணினி வலைப்பின்னலுக்குள் வரும் மற்றும் வெளியே செல்லும் தரவுப் போக்குவரத்தைக் கண்காணித்து, நிர்ணயிக்கப்பட்ட பாதுகாப்பு விதிகளின்படி அங்கீகரிக்கப்படாத அணுகலைத் தடுக்கும் வன்பொருள் அல்லது மென்பொருள் பாதுகாப்பு அமைப்பாகும்.","difficulty":"easy","topic":"இணையப் பாதுகாப்பு"},{"id":999,"subject":"gk","testNumber":10,"question":"வங்கிகள் அல்லது நம்பகமான நிறுவனங்களின் பெயரில் போலி மின்னஞ்சல் மற்றும் போலி இணையதளங்களை அனுப்பி, பயனர்களின் கடவுச்சொல், வங்கி அட்டை விவரங்களைத் திருடும் இணையக் குற்றம் எவ்வாறு அழைக்கப்படுகிறது?","options":["மறைகுறியாக்கம் (Encryption)","ஃபிஷிங் (Phishing)","பிழைத்திருத்தம் (Debugging)","தொகுத்தல் (Compiling)"],"correctAnswer":1,"explanation":"ஃபிஷிங் (Phishing) என்பது வங்கி அல்லது அரசு நிறுவனம் போல் ஆள்மாறாட்டம் செய்து மின்னஞ்சல், குறுஞ்செய்தி அல்லது போலி இணைய இணைப்புகள் மூலம் பயனர்களை ஏமாற்றி, அவர்களின் OTP, கடவுச்சொல் மற்றும் வங்கித் தகவல்களைத் திருடும் இணையவழி மோசடியாகும்.","difficulty":"medium","topic":"இணையப் பாதுகாப்பு"},{"id":1000,"subject":"gk","testNumber":10,"question":"கணினி அமைப்பைச் சேதப்படுத்தவும், தரவுகளைத் திருடவும் அல்லது செயல்பாட்டை முடக்கவும் உருவாக்கப்படும் வைரஸ் (Virus), வோர்ம் (Worm), ட்ரோஜன் ஹார்ஸ் (Trojan Horse) மற்றும் ரான்சம்வேர் ஆகியவை கூட்டாக எவ்வாறு அழைக்கப்படுகின்றன?","options":["நிலைப்பொருள் (Firmware)","இலவச மென்பொருள் (Freeware)","வன்பொருள் (Hardware)","மால்வேர் / தீம்பொருள் (Malware)"],"correctAnswer":3,"explanation":"மால்வேர் (Malware - Malicious Software / தீம்பொருள்) என்பது கணினி அல்லது வலைப்பின்னலுக்குத் தீங்கு விளைவிக்கும் நோக்கத்துடன் உருவாக்கப்பட்ட அனைத்துத் தீய மென்பொருட்களையும் குறிக்கும் பொதுப் பெயராகும். வைரஸ், வோர்ம், ட்ரோஜன் ஹார்ஸ், ஸ்பைவேர் மற்றும் ரான்சம்வேர் ஆகியவை மால்வேரின் முக்கிய வகைகளாகும்.","difficulty":"hard","topic":"இணையப் பாதுகாப்பு"}]);
